      "scenario": "85세 여성. 요양시설에 입소 중이며 알츠하이머 치매(MMSE 18점)로 3년째 지내왔으나, 3일 전부터 밤이면 \"방에 사람이 있다\"며 소리를 지르고 낮에는 불러도 반응이 느리고 축 처져 있다. 시설 직원은 \"치매가 갑자기 심해졌다\"고 보고하였다. 과거력: (1) 알츠하이머 치매, (2) 고혈압, (3) 심부전, (4) 만성 변비(4일째 배변 없음), (5) 절박성 요실금, (6) 골관절염. 오늘 소변이 혼탁하고 냄새가 심하며 소변검사에서 백혈구 3+, 아질산염 양성이 확인되었다. 활력징후: 혈압 104/62mmHg, 맥박 96회/분, 호흡 22회/분, 체온 37.4℃, SpO2 94%. Lab: 나트륨 128mEq/L, 칼륨 3.2mEq/L, BUN/크레아티닌 32/1.3mg/dL, 혈당 68mg/dL, 백혈구 11,800/㎣. 하루 섭취량이 500mL 남짓이고 구강점막이 건조하다. 복용 약물: furosemide, amlodipine, diphenhydramine(불면 시), oxybutynin(요실금), tramadol(무릎 통증). 안경과 보청기는 서랍에 넣어둔 채 착용하지 않고 있으며, 밤에 침대에서 내려오려 해 억제대 적용이 논의되고 있다.",
