          "answer": "① 섬망의 약물치료 원칙 — 비약물 중재(유발요인 교정, 지남력 제공, 수면위생, 감각보조기 착용, 가족 참여)가 우선이며, 약물은 초조·환각으로 본인이나 타인의 안전이 위협될 때만 소량의 항정신병약물을 단기간 사용하고 매일 지속 필요성을 재평가한다. ② 항정신병약물(haloperidol·risperidone·quetiapine)의 주의 — 치매 노인의 행동심리증상에 사용하면 뇌졸중과 사망 위험을 높인다는 경고(black box warning)가 있어 Beers Criteria상 원칙적으로 회피 대상이며, 사용 시 추체외로증상(강직·진전·좌불안석), 기립성 저혈압과 낙상, 진정, 심전도 QT 간격 연장, 삼킴곤란·흡인, 신경이완제악성증후군을 관찰한다. 파킨슨병·루이소체 치매에서 haloperidol은 금기에 준한다. ③ 벤조디아제핀(lorazepam·diazepam)은 섬망과 인지저하를 악화시키고 낙상을 유발하므로 회피하며, 알코올·벤조디아제핀 금단 섬망에서만 예외적으로 1차 약물로 사용한다. ④ 항콜린 부담이 큰 약물의 정리 — 이 대상자가 복용 중인 diphenhydramine(1세대 항히스타민)과 oxybutynin(배뇨장애 약물)은 혼돈·변비·요저류를 유발하고 콜린분해효소억제제의 효과를 상쇄하므로 중단·대체를 검토한다. ⑤ 콜린분해효소억제제(donepezil·rivastigmine·galantamine)는 경도~중등도 알츠하이머병의 1차 약물로 아세틸콜린 분해를 억제해 인지 저하 속도를 늦추는 약이며 완치 약이 아님을 보호자에게 설명하고, 오심·구토·설사·식욕부진, 서맥(투여 전 맥박 60회/분 미만 확인), 불면·생생한 꿈을 관찰한다. ⑥ NMDA 수용체 길항제 memantine(메만틴) — 중등도~중증 알츠하이머에 사용하며 어지럼·변비·혼돈을 관찰하고 신기능 저하 시 감량하며 콜린분해효소억제제와 병용할 수 있다. ⑦ 우울이 동반되면 노인 1차 항우울제는 선택적 세로토닌 재흡수 억제제(SSRI)이며 저나트륨혈증(현재 128mEq/L)과 낙상·출혈 위험을 관찰하고 삼환계 항우울제는 피한다. ⑧ 투약 관리 교육 — 복용 시간을 일정하게 하고 요일별 약상자와 알람을 사용하며 보호자가 복용을 확인하고, 리바스티그민 패치는 매일 부위를 바꾸고 이전 패치를 반드시 제거한다.",
