      "scenario": "81세 남성. 알츠하이머 치매 5년째로 주 5회 주간보호센터를 이용하며 며느리가 주돌봄자이다. 최근 3개월 사이 오후 4시 무렵이면 \"집에 가야 한다\"며 현관을 서성이고, 두 차례 센터 밖으로 나가 인근에서 발견된 적이 있다. 밤에는 자주 깨고 낮에는 졸며, 옷을 혼자 입지 못하고 화장실 위치를 찾지 못한다. 과거력: (1) 알츠하이머 치매(간이정신상태검사 MMSE 15점, 임상치매척도 CDR 2), (2) 고혈압, (3) 전립선비대증, (4) 만성 변비 — 주 1회 딱딱한 변, 배변 시 심하게 힘을 주며 최근 \"설사처럼 묽은 변만 조금씩 샌다\"고 함, (5) 양측 무릎 골관절염, (6) 백내장. 활력징후: 혈압 138/80mmHg, 맥박 76회/분, 체온 36.4℃. Lab: 알부민 3.4g/dL, 혈색소 11.8g/dL, 나트륨 138mEq/L. 3개월간 체중 4kg 감소. 복용 약물: donepezil 10mg, memantine, amlodipine, tamsulosin, 산화마그네슘, 무릎 통증 시 tramadol. 하루 수분 섭취량은 700mL 정도이며 거의 앉아서 지낸다. 며느리는 \"밤에 잠을 못 자서 나도 우울하다, 언제까지 버틸 수 있을지 모르겠다\"고 호소한다.",
