          "answer": "【교정 가능한 위험요인】 ① 고혈압 — 가장 강력한 교정 가능 위험요인으로, 지속적 고혈압이 뇌혈관 내피를 손상시켜 죽상경화와 미세동맥류를 만든다. 목표는 140/90mmHg 미만이며 당뇨를 동반하므로 130/80mmHg 미만을 목표로 한다(현재 178/98mmHg). ② 당뇨 — 고혈당이 죽상경화를 가속하여 뇌경색 위험을 2~4배 높인다. ③ 이상지질혈증 — LDL 콜레스테롤 158mg/dL로 상승되어 있으며 LDL 100mg/dL 미만(고위험군 70mg/dL 미만)을 목표로 스타틴을 사용한다. ④ 심방세동 — 좌심방에 생긴 혈전이 떨어져 나가 심인성 뇌색전을 일으키며, 심방세동 환자의 뇌졸중 위험 점수(CHA2DS2-VASc)로 평가해 항응고제 적응을 결정한다. 항응고제를 자주 거른 것이 직접적 유발요인이다. ⑤ 흡연 40년 — 혈관 내피 손상과 혈액 점도·응고성 증가를 일으키며, 금연하면 5년 내 위험이 비흡연자 수준에 접근한다. ⑥ 과음 — 혈압을 올리고 심방세동을 유발한다. 【교정 불가능한 위험요인】 ⑦ 고령(76세) — 55세 이후 10년마다 위험이 약 2배가 된다. ⑧ 남성 — 같은 연령대에서 발생률이 높다. ⑨ 가족력 — 아버지가 뇌졸중으로 사망하여 유전적 혈관 취약성과 생활습관을 공유한다. ⑩ 일과성 뇌허혈발작(TIA) 과거력 — 3개월 전 일과성 증상이 있었고 TIA 후 90일 이내 재발 위험이 가장 높다. 이 밖에 이 대상자에게서 함께 확인해야 할 요인으로 비만·운동부족·대사증후군, 폐쇄성 수면무호흡이 있으며, 이들은 고혈압·당뇨·이상지질혈증을 함께 악화시킨다.",
