          "answer": "① 활력징후와 의식수준 사정 — GCS(글래스고 혼수척도, 눈뜨기 4 + 언어 5 + 운동 6 = 15점 만점)로 의식을 정량화하고 혈압·맥박·호흡·체온·산소포화도를 감시하여 악화를 조기에 발견하기 위함이다(현재 GCS 14점, 혈압 178/98mmHg). ② 신경학적 사정 — 동공 크기와 대광반사, 사지 근력(도수근력검사 0~5등급), 감각, 안면 대칭, 언어(실어증·구음장애), 연하 반사, 편측 무시를 확인하고 NIHSS(0~42점)로 결손의 중증도를 점수화하여 경과를 비교하기 위함이다. 또한 FAST와 함께 마지막으로 정상이었던 시각(오전 7시 50분)을 반드시 기록하는데, 이 시각이 혈전용해제 투여 가능 여부를 결정하기 때문이다. ③ 뇌 CT(전산화단층촬영) — 응급 1순위 검사로 뇌출혈과 뇌경색을 감별하기 위함이다. 두 질환은 치료가 정반대(경색은 혈전용해·항혈전, 출혈은 지혈·혈압조절·수술)이므로 반드시 먼저 구분해야 하며, 확인 전에는 항혈전제를 투여하지 않는다. ④ 뇌 MRI와 확산강조영상, 필요 시 뇌혈관조영(CT·MR 혈관조영) — 발병 수 시간 이내의 초급성 병소와 크기, 뇌혈관 협착·폐색 부위와 동맥류를 확인하기 위함이다. ⑤ 심전도와 24시간 홀터, 심초음파, 경동맥 초음파 — 불규칙한 맥박 112회/분의 원인인 심방세동을 확인하고 좌심방 혈전·판막질환 등 색전원을 규명하기 위함이다. ⑥ 혈액검사 — 혈당(저혈당은 뇌졸중과 유사한 증상을 낸다), 지질검사, 전혈구계산, 응고검사(PT·aPTT·INR), 전해질, 신장·간기능으로 감별진단과 혈전용해 적응을 판단하기 위함이다. ⑦ 연하 사정 — 경구 섭취 전 침상 물 삼킴검사를 시행하고, 사레와 젖은 목소리가 있으므로(산소포화도 저하 여부도 함께 확인) 금식(NPO) 후 VFSS(비디오투시연하검사)로 흡인 여부를 확진하기 위함이다.",
