          "answer": "levodopa/carbidopa는 레보도파가 뇌혈관장벽을 통과해 뇌에서 도파민으로 전환되어 부족한 도파민을 보충하고, 카비도파가 말초에서의 전환을 막아 오심을 줄이고 뇌 도달량을 높이는 약물이다. 장기복용 시 다음 부작용이 나타난다. ① 약효소진(wearing-off)과 ON-OFF 현상 — 약효 지속시간이 짧아져 다음 복용 전에 증상이 재발하고 갑자기 몸이 굳었다 풀렸다 한다. 중재: 복용 시각을 정확히 지키게 하고 복용 간격 조정·서방정·보조약 추가를 의료진과 상의하며, 약효가 가장 좋은 시간대에 이동·운동·목욕을 배치한다. ② 이상운동증(dyskinesia) — 약효가 최고일 때 얼굴·사지가 저절로 꿈틀거리는 불수의 운동이 나타나며 용량을 줄이면 호전되므로 발생 시각과 양상을 기록해 보고한다. ③ 심혈관계 부작용 — 기립성 저혈압이 흔하고(현재 기립 시 수축기 28mmHg 하강) 부종·부정맥이 생길 수 있다. 중재: 체위를 천천히 바꾸고 일어나기 전 1~2분 걸터앉게 하며 기립 전후 혈압과 체중·부종을 관찰한다. ④ 위장관계 부작용 — 오심·구토·식욕부진. 중재: levodopa는 공복(식전 30분~1시간) 복용이 원칙이며, 고단백 식이의 아미노산이 레보도파의 장 흡수와 뇌 이동을 경쟁적으로 방해하므로 고단백 식사와 시간 간격을 두거나 단백질을 저녁에 몰아 섭취하도록 남편에게 교육한다. 오심이 심할 때만 예외적으로 소량의 저단백 간식과 함께 복용한다. ⑤ 정신증상 — 생생한 꿈·악몽, 환각·망상, 충동조절장애가 나타나면 즉시 보고하고, 소변이 붉거나 검게 변색될 수 있으나 무해함을 미리 설명한다. 또한 절대 임의로 중단하지 않도록 교육하는데, 갑작스러운 중단은 고열·근강직·의식저하를 특징으로 하는 파킨슨 위기를 유발할 수 있기 때문이다. 도파민을 차단하는 haloperidol과 항구토제 metoclopramide는 파킨슨 증상을 급격히 악화시키므로 금기에 준한다.",
