          "answer": "【진단 1】 심박출량 감소에 따른 나트륨·수분 저류와 관련된 체액과다 — ① 매일 같은 시간(아침 기상 후 배뇨 뒤, 같은 옷차림)에 체중을 측정하고 하루 1kg, 3일 내 2kg 이상, 일주일 2kg 이상 증가하면 즉시 보고한다(현재 3일간 2.5kg 증가). 체중은 체액 저류의 가장 예민한 지표이다. ② 섭취량과 배설량(I/O)을 매 근무조 기록하고 나트륨을 2g/일 이하로 제한하며 필요 시 수분을 1,000~1,500mL/일로 제한한다. ③ 말초 부종(함요부종 정도), 경정맥 확장, 복부 팽만, 폐음 청진 시 수포음, 야간 발작성 호흡곤란과 기좌호흡을 사정한다. ④ 이뇨제는 야간뇨를 피해 아침에 투여하고, 투여 후 소변량과 함께 저칼륨혈증(근육 약화·경련·부정맥), 탈수, 기립성 저혈압을 관찰하며 전해질 결과를 확인한다. ⑤ 부종 부위의 피부는 손상되기 쉬우므로 압박을 피하고 다리를 심장보다 높게 올리며 매일 피부를 관찰한다. ⑥ 저염 식단의 실제 방법(국물 남기기, 젓갈·장아찌·가공식품 제한)을 교육하고 칼륨염 대체 소금은 임의로 쓰지 않게 한다. 【진단 2】 심근의 산소 공급과 요구 불균형과 관련된 급성 통증(흉통) 및 죽음에 대한 불안 — ① 급성기에는 즉시 활동을 중단시키고 침상안정을 취하게 하며, 통증의 부위·양상·강도(NRS)·방사·지속시간과 유발·완화 요인을 사정하고 호흡수·피부색을 관찰한다. ② 처방에 따라 산소를 투여하고 니트로글리세린을 설하로 투여하며, 투여 전후 혈압을 측정하고 5분 간격으로 최대 3회까지 투여해도 완화되지 않으면 즉시 보고한다. ③ 심전도와 심근효소를 연속 확인하여 협심증과 심근경색을 감별하고 부정맥 발생에 대비하며, 통증이 지속되면 처방된 모르핀을 투여하고 호흡·혈압을 감시한다. ④ 죽음에 대한 공포와 불안을 표현하도록 격려하고 조용하고 편안한 환경을 제공하며 모든 처치와 치료계획을 쉬운 말로 미리 설명하여 예측 가능성을 높인다. ⑤ 흉통 재발 시 대처법(하던 일 즉시 멈추고 옷·벨트를 느슨하게 한 뒤 무릎을 구부려 앉아 안정 → 니트로글리세린 설하 투여 → 119 연락 → 5분 이상 지속되면 지체 없이 응급실 → 의식을 잃으면 즉시 심폐소생술)을 가족과 함께 반복 교육하고 되돌려 시범하게 한다.",
