      "scenario": "79세 여성. 심방세동으로 warfarin을 5년째 복용 중이며, 심부전 악화로 입원하였다가 퇴원을 앞두고 있다. 최근 잇몸에서 피가 자주 나고 팔에 이유 없는 멍이 여러 개 생겼다. 과거력: (1) 심방세동, (2) 만성 심부전, (3) 2형 당뇨 — glimepiride와 취침 전 지속형 인슐린 사용, (4) 고혈압, (5) 골다공증, (6) 백내장으로 시력 저하(약병 글씨를 읽기 어려움), (7) 만성신질환(추정 사구체여과율 48mL/분/1.73㎡). 활력징후: 혈압 128/76mmHg, 맥박 58회/분(불규칙), 호흡 18회/분, 체온 36.5℃. Lab: PT/INR 3.8, 칼륨 3.1mEq/L, 크레아티닌 1.4mg/dL, 당화혈색소 6.8%, 공복혈당 82mg/dL. 복용 약물: warfarin, digoxin 0.25mg/일, furosemide, enalapril, glimepiride, 지속형 인슐린, 칼슘·비타민D. 지난 2주 사이 새벽에 두 차례 갑자기 멍해지고 식은땀 없이 힘이 빠졌으나 아침 식사 후 회복되었다고 하며, 최근 식욕이 없어 저녁을 자주 거른다. 며칠 전부터 물체 주위에 노란 테두리가 보인다고도 호소한다.",
