          "answer": "① 응고검사 확인 — warfarin은 비타민K 의존성 응고인자(II·VII·IX·X)의 합성을 억제하는 경구 항응고제이므로 사용 전과 사용 중 PT와 INR을 확인한다. PT 정상은 11~15초(활성도 70~120%), INR 정상은 0.8~1.2이며 치료 목표 INR은 2~3(기계판막은 2.5~3.5)이다. 현재 INR 3.8에 잇몸출혈·자반이 있으므로 다음 용량을 보류하고 즉시 보고하며, 처방에 따라 비타민K 투여를 준비한다. 덧붙여 INR이 4를 초과하면서 출혈 징후가 있으면 뇌출혈·위장관출혈 위험이 한층 커진다. INR은 용량 조정기에는 주 1~2회, 안정되면 월 1회 측정한다. ② 적응증과 금기 확인 — 적응증은 심방세동의 혈전, 심부정맥혈전증·폐색전증의 예방과 치료이며, 금기는 개방된 상처, 중증 간·신질환, 활동성 위궤양 등 출혈성 병변, 최근 뇌출혈, 임신이다. ③ 효과 발현 시점 설명 — 복용 후 24시간 이내에 혈전 생성능력이 감소하기 시작하지만 충분한 항응고 효과는 3~5일이 지나야 나타나므로 초기에는 헤파린과 겹쳐 사용하며 그동안 임의로 중단하지 않도록 설명한다. ④ 복용 방법 교육 — 처방대로 매일 일정한 시간에 복용하고(용량은 PT·INR에 따라 조정됨), 당일 복용을 잊었으면 그날 늦게라도 복용하되 다음 날 기억났다면 2회분을 한꺼번에 복용하지 않도록 교육한다. ⑤ 출혈 징후 교육 — 코피, 잇몸출혈, 혈뇨, 검은 변·혈변, 이유 없는 멍, 지혈 지연, 갑작스러운 심한 두통(뇌출혈 의심)이나 복통(복부 출혈 의심)이 있으면 즉시 병원에 오도록 하고, 부드러운 칫솔과 전기면도기를 사용하며 넘어지지 않도록 주의시킨다. ⑥ 식이·병용약물 교육 — 비타민K가 많은 녹색 잎채소·청국장·녹즙은 금지가 아니라 매일 비슷한 양으로 일정하게 섭취하고, 아스피린·비스테로이드소염제(NSAIDs)·일부 항생제·은행잎·오메가3는 출혈을 늘리므로 반드시 의료진과 상의하게 한다. 과량 시 해독제는 비타민K이다. 참고로 DOAC(직접작용 경구항응고제 apixaban·rivaroxaban·edoxaban)은 INR 감시가 필요 없고 식이 제한이 적지만, 반감기가 짧아 복용 시각을 반드시 지켜야 하고 신기능에 따라 용량을 조정한다. ⑦ 동시에 digoxin 0.25mg/일은 Beers Criteria상 0.125mg/일을 초과하여 회피 대상이며, 맥박 58회/분과 노란 테두리가 보이는 시각장애, 식욕부진은 디곡신 독성을 시사하므로 투여 전 1분간 심첨맥박을 측정해 60회/분 미만이면 보류·보고하고, furosemide에 의한 저칼륨혈증(3.1mEq/L)이 독성을 악화시키므로 칼륨을 반드시 감시한다.",
