          "answer": "① 당화혈색소와 공복혈당·자가혈당측정 — 당화혈색소는 최근 2~3개월의 평균 혈당을 반영하며 6.5% 이상이면 당뇨이다(현재 8.6%). 노인은 저혈당 위험과 기대여명·동반질환을 고려해 목표를 계층화하는데, 건강한 노인은 7.0~7.5%, 복합이환·기능저하 노인은 8.0~8.5%를 목표로 한다. 자가혈당은 공복·식후 2시간·취침 전을 기록하여 하루 중 변동과 저혈당 발생 시각을 파악하기 위함이다. ② 발 검진(10g 모노필라멘트, 128Hz 음차, 발목반사, 침통각) — 발바닥 압각과 진동감각을 검사하여 보호감각 소실 여부를 확인하기 위함이며, 감각이 없으면 궤양 고위험군으로 분류한다(이 대상자는 통증 없이 상처가 생겼다). ③ 발의 혈류 사정 — 족배동맥·후경골동맥 촉지, 발의 색·온도·모발 소실·발톱 비후 관찰, 발목상완지수(ABI, 0.9 미만이면 말초동맥질환) 측정으로 순환장애와 치유 지연 요인을 확인하기 위함이다. ④ 상처 사정과 배양검사 — 크기·깊이·바닥 조직·삼출물·냄새와 감염 징후(발적·열감과 발열 여부 — 현재 37.1℃로 정상이나, 노인은 감염이 있어도 발열이 없을 수 있다)를 기록하고, 감염이 의심되면 항생제 투여 전에 조직 배양을 시행하여 원인균과 감수성을 확인하기 위함이다. ⑤ 신장 합병증 검사 — 소변 미세알부민/크레아티닌 비와 추정 사구체여과율(eGFR, 현재 42)을 확인하여 당뇨병성 신증의 진행을 평가하고 metformin 등 약물 용량을 조정하기 위함이다(eGFR 30 미만이면 metformin 금기). ⑥ 안저검사(산동 후 망막검사) — 매년 시행하여 당뇨망막병증의 진행을 확인하기 위함이며, 시력 저하는 낙상·투약오류·발 관리 실패로 이어진다. ⑦ 심혈관 위험 평가 — 혈압(목표 140/90mmHg 미만), 지질검사(저밀도지단백 LDL 100mg/dL 미만), 심전도를 확인하고, 노인 당뇨는 무통성 심근경색이 흔하므로 피로·호흡곤란·소화불량 등 비전형 증상을 함께 사정하기 위함이다. ⑧ 노인 특이 사정 — 저혈당 병력, 인지기능(간이정신상태검사 MMSE)·시력·손 기능(혈당기 조작 가능 여부), 영양(간이영양상태평가 MNA)·체중, 우울, ADL·IADL 특히 투약관리 능력, 독거 여부와 돌봄 자원을 확인하기 위함이다.",
