          "answer": "【진단 1】 말초신경병증 및 말초순환장애와 관련된 피부통합성 장애(당뇨발 궤양) — ① 매일 발 전체(발가락 사이·발바닥·발뒤꿈치)를 관찰하고 10g 모노필라멘트와 음차로 보호감각을, 족배동맥 촉지와 발목상완지수로 혈류를 정기 사정한다. ② 발은 미지근한 물(37℃ 이하, 손목이나 팔꿈치로 온도 확인)로 5분 이내 씻고 발가락 사이까지 두드려 완전히 말린 뒤, 발가락 사이를 제외한 부위에만 보습제를 바른다. ③ 발톱은 목욕 후 부드러워졌을 때 일자로 자르고, 티눈·굳은살·물집은 절대 스스로 자르거나 티눈고를 붙이지 않고 의료진에게 의뢰한다. ④ 맨발로 다니지 않게 하고 실내에서도 신발과 면양말을 신게 하며, 신발 안에 이물질이 있는지 확인하고 전기장판·핫팩·난로에 발을 직접 대지 않도록 한다(감각이 없어 화상을 입고도 모른다). ⑤ 혈당을 목표 범위로 조절하고 금연시키며, 상처 부위의 압력을 제거(체중 부하 감소)하고 무균적 상처간호를 시행하며 발적·부종·고름·냄새·색 변화가 있으면 즉시 보고한다. 【진단 2】 불규칙한 식사 및 혈당강하제 사용과 관련된 불안정한 혈당 수치의 위험 — ① 정해진 시간에 자가혈당을 측정해 기록하게 하고 식사·활동·약물과 혈당 변화의 관계를 함께 검토한다. ② 식사를 거르지 않도록 하고 인슐린·설폰요소제 투여 시각과 식사 시각을 맞추며, 식사량이 평소보다 적었으면 용량 조정을 의료진과 상의한다. ③ 저혈당(70mg/dL 미만) 시 의식이 있으면 즉시 속효성 탄수화물 15g을 주고 15분 뒤 재측정하여 여전히 70mg/dL 미만이면 반복한다(15-15 규칙). 의식이 없거나 삼킬 수 없으면 절대 경구로 주지 말고 옆으로 눕힌 뒤 글루카곤 투여 또는 50% 포도당 정맥주사를 준비하고 즉시 119에 연락한다. ④ 노인은 발한·떨림 없이 혼돈·어눌한 말·낙상·기면만 나타날 수 있으므로 갑작스러운 의식·행동 변화가 있으면 우선 혈당을 측정하고, 감염·발열 등 아픈 날에는 인슐린을 임의로 중단하지 않고 혈당을 3~4시간마다 측정하며 수분을 충분히 섭취하고 혈당 300mg/dL 이상이거나 구토가 지속되면 내원하도록 한다.",
