          "q": "이 대상자에게서 폐렴 발생 위험을 높인 요인 10가지를 근거와 함께 서술하시오.",
          "answer": "① 흡인 — 뇌경색 후 연하곤란이 있어 식사 중 사레가 잦고 목소리가 젖으며, 위식도역류질환까지 있어 구인두 분비물과 음식물, 역류한 위 내용물이 기도로 넘어간다. 노인 폐렴의 가장 흔한 경로이며 우하엽 침윤이라는 이 대상자의 방사선 소견도 흡인성 폐렴에 합당하다. ② 구강위생 불량 — 편마비와 치매로 스스로 칫솔질과 틀니 관리를 하지 못하면 구강 내 세균이 증식하여 흡인 시 그대로 폐로 들어간다. ③ 면역노화와 기침반사·섬모운동 저하 — 81세 고령으로 감염을 막고 분비물을 밖으로 내보내는 방어기전이 모두 약해져 화농성 가래를 스스로 뱉지 못한다. ④ 기존 만성 폐질환 — 만성폐쇄성폐질환(COPD) 12년으로 FEV1/FVC 0.52, FEV1 예측치 44%의 중증 기류제한이 있어 분비물 정체와 기도 내 세균 집락이 잘 생긴다. ⑤ 장기 흡연력 — 45년간 하루 2갑(90갑년)의 흡연으로 섬모가 파괴되고 기도 염증이 남아 폐렴·COPD·폐암 위험을 모두 높인다. ⑥ 영양불량과 저알부민혈증 — 알부민 2.9g/dL, 총단백 5.4g/dL, 1년간 6kg 감소(체질량지수 18.4)로 호흡근이 약해지고 면역글로불린 생산이 줄어 감염에 취약하다. ⑦ 부동과 와상 상태 — 침상과 휠체어를 오가는 생활로 심호흡과 기침을 충분히 하지 못해 무기폐와 분비물 정체가 생긴다. ⑧ 동반 만성질환 — 당뇨(공복혈당 168mg/dL, 당화혈색소 7.8%의 고혈당이 백혈구 기능을 떨어뜨림), 심부전(좌심실 구혈률 45%로 폐 울혈), 뇌경색이 겹쳐 있다. ⑨ 약물 — 위산억제제인 esomeprazole(양성자펌프억제제, PPI) 장기 복용은 위 내 산도를 낮춰 세균 증식을 늘리고, 수면제 zolpidem은 의식과 기침반사를 떨어뜨려 야간 흡인을 조장하며, 흡입 스테로이드(fluticasone)는 국소 면역을 억제해 폐렴 위험을 높인다. ⑩ 예방접종 미실시 — 인플루엔자·폐렴구균 백신을 한 번도 맞지 않아 발생률과 사망률이 크게 높아진 상태이다. ⑪ 집단생활과 반복 입원 — 요양시설 거주와 최근 1년간 2회의 급성악화 입원력은 다제내성균 폐렴의 위험을 높인다. 또한 이 대상자처럼 노인 폐렴은 발열·기침·화농성 가래의 전형적 3징 없이 식욕부진·기력 저하·혼돈(섬망)·낙상·빈호흡만으로 나타나는 경우가 흔하므로, 이틀 전부터의 식사량 감소와 야간 혼돈, 호흡수 28회/분(24회/분 이상)의 빈호흡을 폐렴의 첫 신호로 해석해야 한다.",
