          "q": "이 대상자와 요양시설 요양보호사·가족에게 시행할 퇴원 교육 8가지를 서술하시오.",
          "answer": "① 입술 오므리기 호흡(pursed-lip breathing)을 교육한다 — 코로 2초간 들이쉬고, 촛불을 끄듯 입술을 오므려 4~6초간 천천히 길게 내쉰다. 기도 내 압력을 유지해 소기도 허탈을 막아 갇힌 공기를 빼내고 호흡곤란을 줄인다. ② 횡격막(복식) 호흡을 교육한다 — 한 손은 가슴, 한 손은 배에 얹고 배가 올라오도록 코로 들이쉰 뒤 배가 꺼지도록 내쉰다. 보조근 사용을 줄여 호흡 효율을 높인다. ③ 효과적인 기침과 가래 배출을 교육한다 — 앉아서 상체를 약간 앞으로 숙이고 심호흡 2~3회 후 두 번에 나누어 짧게 기침한다. 기상 직후와 취침 전에 시행하고, 기관지확장제 흡입 15분 뒤에 하면 더 잘 나온다. ④ 흡입기 사용법과 관리를 교육하고 되돌려 시범(teach-back)으로 확인한다 — 사용 순서(기관지확장제 → 스테로이드), 사용 후 입 헹구고 뱉기, 스페이서 사용, 남은 용량 확인, 기구 세척을 요양보호사와 함께 익히게 한다. ⑤ 금연을 유지하도록 교육한다 — 금연은 COPD의 진행을 늦추는 유일한 방법이므로 5년째 유지 중인 금연을 계속하도록 격려하고, 재흡연 위험 상황에는 금연 상담·니코틴 대체제·금연클리닉을 연계하며 가족과 같은 방 입소자의 실내 흡연도 금하도록 한다. ⑥ 예방접종을 교육한다 — 인플루엔자 백신을 매년 1회, 폐렴구균 백신을 65세 이후 1회 접종하고 코로나19 백신도 권고에 따라 맞도록 하며, 한 번도 접종한 적이 없는 이 대상자는 퇴원 전 접종 일정을 반드시 잡는다. ⑦ 에너지 절약법을 교육한다 — 앉아서 세면·옷 입기, 자주 쓰는 물건 허리 높이에 두기, 무거운 물건은 들지 말고 밀기, 일을 나누어 중간중간 쉬기, 숨이 찰 때는 멈춰서 입술 오므리기 호흡하기. ⑧ 영양 관리를 교육한다 — 소량씩 자주(하루 5~6회) 고단백·고열량으로 먹고, 식전에 쉬고 식사 중에는 말을 줄이며, 가스가 차는 음식과 과식을 피하고 체중을 주 1~2회 기록해 51kg에서 더 줄지 않도록 한다. ⑨ 수분 섭취와 환경 관리를 교육한다 — 하루 2,000mL 내외의 수분으로 가래를 묽게 하되 심부전이 있으므로 처방된 제한 범위 내에서 조절하고, 실내 습도 40~60%를 유지하며 찬 공기·미세먼지·연기·강한 냄새를 피하고 외출 시 마스크를 착용한다. ⑩ 악화 징후와 대처를 교육한다 — 숨참이 평소보다 심해짐, 가래의 양 증가와 색 변화(누렇거나 초록), 38℃ 이상 발열, 가슴 답답함, 발목 부종, 의식이 흐려지거나 처짐, 입술·손톱의 청색증이 있으면 즉시 병원에 연락하도록 하고, 응급 시 사용할 약과 연락처를 적어 붙여 둔다. 가정이나 시설에서 산소를 쓰는 경우 'COPD 환자는 만성 이산화탄소(CO2) 저류로 저산소가 유일한 호흡 자극원이므로, 고농도 산소 투여 시 호흡 자극이 억제되어 CO2 저류가 악화(CO2 혼수)될 수 있어 저유량(1~2L/분) 산소를 유지한다'는 원리를 설명하고, 숨차다고 임의로 유량을 올리지 않도록 교육한다. ⑪ 흡인성 폐렴 예방을 교육한다 — 식사는 똑바로 앉아 턱을 당기고 소량씩 천천히 하며, 식후 30분 이상 앉아 있게 하고, 매 식후와 취침 전 칫솔질과 틀니 세척으로 구강을 청결히 하며, 누워서 음식이나 물을 먹이지 않도록 요양보호사에게 시범과 함께 교육한다. 위식도역류가 있으므로 취침 시 침상머리를 30도 이상 올리고 취침 직전 식사를 피하도록 한다.",
