          "answer": "① 세계보건기구(WHO) 3단계 진통사다리 적용 — 경한 통증은 비마약성 진통제(아세트아미노펜·비스테로이드소염제 NSAIDs), 중등도는 약한 마약성 진통제(코데인·tramadol), 심한 통증은 강한 마약성 진통제(모르핀·옥시코돈·펜타닐)를 사용하며, 이 대상자처럼 NRS 7점의 심한 통증이면 단계를 건너뛰어 바로 강한 진통제를 쓸 수 있다. 골전이 통증에는 스테로이드·비스포스포네이트, 신경병증성 통증에는 가바펜틴·프레가발린 등 보조진통제를 병용한다. ② 모르핀(morphine)의 사용 원칙 — 경구를 우선하고, 시간을 정해 규칙적으로(by the clock) 투여하며, 사다리에 따라, 개인에 맞는 용량으로 준다. 마약성 진통제에는 용량을 올려도 효과가 더 늘지 않는 천장효과가 없어 통증에 따라 증량할 수 있으나, 이 대상자는 크레아티닌 2.1mg/dL·사구체여과율 38mL/min의 신기능 저하로 대사산물이 축적되어 진정·근간대경련이 생길 수 있으므로 감량하고 면밀히 관찰한다. ③ 돌발통 관리 — 규칙 투여 중에도 갑자기 심해지는 통증에는 속효성 제제(현재 속효성 모르핀 설하)를 하루 총 용량의 약 10%로 추가 투여하고, 구제약을 하루 3~4회 이상 쓰면 기본 용량 증량을 검토한다. ④ 마약성 진통제의 부작용 관리 — 변비는 내성이 생기지 않아 복용 내내 지속되므로 처음부터 완하제를 함께 처방하고(현재 처방 유지), 오심·구토와 졸림은 대개 3~5일 내 내성이 생겨 좋아지며, 호흡억제는 통증이 있는 상태에서 적정 용량을 쓰면 드물다. 소변저류·가려움·구강건조·근간대경련을 관찰한다. ⑤ 오해 교정(교육이 곧 간호) — 통증에 맞게 사용하면 중독되지 않고, 아껴 둘 필요가 없으며, 마약성 진통제를 쓴다고 수명이 줄지 않고 오히려 편안하게 지내는 데 도움이 됨을 대상자와 아들·딸에게 반복 설명한다. 통증조절을 위한 마약성 진통제 사용은 안락사나 수명 단축이 아니다. ⑥ 펜타닐(fentanyl) 경피 패치 관리 — 72시간마다 교체하며 털이 없는 마른 피부에 붙이고 부착 부위를 매번 바꾼다. 효과 발현까지 12~24시간이 걸리므로 어제 부착 후 그 사이에는 기존 진통제(속효성 모르핀)로 통증을 조절하고, 현재 체온 37.6℃의 발열과 전기장판·온찜질은 흡수를 급격히 늘려 과량 위험이 있으므로 피하며, 사용한 패치는 접어서 안전하게 폐기한다. ⑦ 노인에게 피해야 할 진통제 — meperidine(페티딘)은 대사산물이 축적되어 경련과 섬망을 유발하므로 Beers Criteria상 노인 금기이고(신부전이 있는 이 대상자에서 특히 위험), NSAIDs 장기 사용은 위장출혈·신기능 악화·심부전 악화를 일으키므로 주의한다. ⑧ 경구 불가 시 경로 변경과 처방 정리 — 삼킴이 어려워진 지금처럼 피하 지속주입, 경피 패치, 설하·직장 투여로 전환하고, 꼭 필요한 약(진통제·항불안제·항구토제·항분비제)만 남기고 나머지(스타틴·비타민·혈압약 등)는 중단하는 처방 정리(deprescribing)를 시행한다. ⑨ 임종기 증상별 약물 — 호흡곤란에는 저용량 모르핀, 기도 분비물(그르렁거림)에는 항콜린제(글리코피롤레이트·스코폴라민, 조기에 사용해야 효과적), 오심·구토에는 haloperidol 소량이나 온단세트론, 임종 섬망과 심한 초조에는 haloperidol 소량, 불안·경련에는 lorazepam이나 미다졸람을 사용한다(생애말기는 벤조디아제핀 회피 원칙의 예외로, 안위를 우선한다). ⑩ 약물 관리와 안전 교육 — 마약성 진통제는 잠글 수 있는 곳에 보관하고 남은 약은 약국·의료기관에 반납하며, 투여 시각과 통증 점수(NRS·PAINAD)를 기록지에 적어 방문간호사·가정호스피스팀 방문 시 함께 검토하도록 딸에게 교육한다.",
