      "scenario": "장기요양시설에 입소하고 있는 노인에게 투베르쿨린 피부반응검사(PPD, purified protein derivative)를 실시한 결과, 주사 부위의 경결(induration) 크기가 3mm로 측정되었다. 한편 같은 시설에 활동성 폐결핵을 진단받은 환자가 새로 입소하였고, 위 대상자는 이 환자와 같은 방을 사용하게 되었다. 시설에서는 밀접접촉자에 대한 예방적 isoniazid(INH) 투여를 고려하고 있다. 시설 거주 노인 중에는 뚜렷한 발열·오한 없이 기침만 오래 지속되어 천식으로 알고 지내던 대상자도 있어, 결핵 발견이 늦어지는 일이 반복되고 있다.",
