      "scenario": "결핵을 새로 진단받은 노인 대상자에게 isoniazid(INH), rifampin(RFP), pyrazinamide(PZA)가 처방되어 복용을 시작하였고, INH와 rifampin은 6개월 처방되었다. 이 대상자는 파킨슨병 기왕력이 있어 항파킨슨 약물을 복용해 왔고, 그 밖에도 여러 만성질환 약물을 함께 복용 중이다. 투약 시작 며칠 뒤 대상자가 \"소변이 오렌지색으로 나온다\"며 놀란 목소리로 전화를 걸어왔다. 노인전문간호사는 투약 전 확인해야 할 과거병력과 약물상호작용을 다시 점검하고 있다.",
