          "q": "\"소변이 오렌지색으로 나온다\"는 전화에 대한 노인전문간호사의 적절한 반응을 근거와 함께 서술하고, 이 대상자에게 항결핵제를 투여하기 전에 반드시 확인해야 할 과거병력과 그 이유를 함께 서술하시오.",
