          "q": "파킨슨병 기왕력이 있는 이 대상자에게 INH를 투여할 때 약물상호작용과 관련하여 반드시 확인해야 할 사항을 제시하고, 그 기전과 간호중재를 서술하시오.",
          "answer": "① 확인할 사항 — 이 대상자가 레보도파(levodopa)를 사용하고 있는지를 반드시 확인해야 한다. ② 기전 — INH는 말초신경병증을 유발할 수 있어 이를 예방하기 위해 피리독신(비타민 B6)을 함께 투여하는 것이 원칙이다. 그런데 피리독신은 레보도파의 효과를 감소시킬 수 있다. 따라서 파킨슨병으로 레보도파를 복용하는 대상자에게 INH와 피리독신을 함께 투여하면 파킨슨 증상(서동, 강직, 진전, 보행동결)이 악화될 수 있다. ③ 간호중재 — 투약 시작 전 복용 중인 항파킨슨 약물의 종류와 용량, 복용 시간을 정확히 확인하고 처방의와 공유한다. ④ 피리독신 병용의 필요성과 레보도파 상호작용을 함께 고려하여 용량·제형 조정 여부를 상의한다(레보도파 단독 제제인지, 말초 탈탄산효소억제제가 함께 든 복합제인지에 따라 영향 정도가 달라진다). ⑤ 투약 후에는 파킨슨 증상의 변화를 매일 관찰하고 기록한다 — 보행 속도, 일어서기와 옷 입기 등 일상생활동작 수행 정도, 진전과 강직의 변화, 약효가 떨어지는 시간대(wearing-off)의 출현 여부를 확인한다. ⑥ 동시에 INH의 말초신경병증 징후(손발 저림·화끈거림·감각 이상)도 관찰하여, 피리독신을 줄이거나 중단할 경우 나타날 수 있는 부작용을 놓치지 않는다. ⑦ 파킨슨병 노인은 증상 악화가 곧 낙상과 흡인으로 이어지므로, 증상 변화가 관찰되면 즉시 보고하고 보행 보조와 연하 사정을 강화한다.",
