          "answer": "① 의심되는 만성 질환 — 만성폐쇄성폐질환(COPD)이다. 흡연은 COPD의 가장 흔한 위험요인이며, 이 대상자는 흡연력이 있고 현재도 흡연 중이다. 만성적인 기침, 점차 증가하는 가래, 그리고 매일 지속되며 서서히 악화되는 호흡곤란은 COPD의 전형적인 세 가지 증상이다. 따라서 흡연력이 있는 노인에서 이러한 증상이 나타나면 COPD를 가장 먼저 의심해야 한다. ② 현재 악화의 성격 — 청진에서 호흡음이 깨끗하고 발열이 없으며 흉부 방사선사진이 정상이므로 폐렴은 배제할 수 있고, 가래 섞인 기침을 주증상으로 하는 급성 기관지염으로 볼 수 있다. ③ 우선 고려할 약물 — 기관지확장제인 알부테롤(albuterol, salbutamol) 흡입이다. 급성 기관지염에서 나타나는 기침 증상은 기관지확장제로 조절할 수 있으며, 흡입 제형은 작용이 빠르고 전신 부작용이 적다. ④ 배제되는 약물의 이유 — erythromycin과 tetracycline은 항생제로, 흉부 방사선사진이 정상이고 세균성 폐렴이 배제된 상태에서는 우선순위가 낮다. rifampin은 항결핵제이므로 해당되지 않는다. mucomyst(아세틸시스테인) 흡입은 점액의 점도를 낮추는 거담제로, 기관지확장제보다 우선하는 약물은 아니다. ⑤ 비약물 관리 두 가지 — 첫째, 금연이다. 금연은 COPD의 진행을 늦추는 가장 근본적인 방법이며 기도 자극과 가래 생성을 줄인다. 금연 상담과 금연클리닉을 연계하고 가족의 실내 흡연도 금하게 한다. 둘째, 충분한 수분 섭취이다. 심부전·신부전 등의 제한이 없다면 하루 2,000mL 내외의 수분을 섭취하게 하여 가래를 묽게 만들고 배출을 돕는다.",
