          "answer": "① 가장 도움이 되는 검사 — 폐기능검사(PFT)이다. ② 이유 — 이 대상자는 18개월간 지속된 만성 기침과 점점 심해지는 호흡곤란이 주된 문제인데, 흉부 방사선사진이 정상이어서 폐렴·폐부종·종괴 같은 실질 병변이 배제되고, 심전도가 정상이며 부종과 곤봉형 손가락도 없어 심장성 원인과 만성 저산소 질환의 가능성이 떨어지며, 산소포화도 97%로 안정 시 저산소혈증도 없다. 영상과 심전도가 정상인데도 만성 기침과 호흡곤란이 지속되는 경우에는 영상으로 드러나지 않는 기도 폐쇄성 질환(천식, 만성폐쇄성폐질환 등)을 확인해야 하며, 이를 객관적으로 판정할 수 있는 검사가 폐기능검사이다. FEV1/FVC와 FEV1을 측정하고 기관지확장제 투여 후 가역성을 확인하면 천식과 COPD를 감별할 수 있다. ③ 적절하지 않은 처치 첫째 — oseltamivir 5일 투여이다. oseltamivir는 인플루엔자 치료제인데 이 대상자는 발열이 없고(체온 36.7℃) 급성 인플루엔자를 시사하는 소견이 없으며 증상이 18개월간 지속된 만성 경과이므로 적응증이 되지 않는다. ④ 적절하지 않은 처치 둘째 — 탈조건화(deconditioning)를 줄이기 위한 운동처방이다. 원인 진단이 이루어지지 않은 상태에서 증상을 체력 저하 탓으로 돌리고 운동만 처방하면, 치료 가능한 기도질환의 진단이 늦어진다. 운동재활은 진단이 확정된 뒤 치료와 병행할 중재이지 진단 단계의 우선순위가 아니다. ⑤ 운동부하 심전도와 심초음파도 심전도가 정상이고 흉통·부종 등 심장성 소견이 없는 현 단계에서는 우선순위가 떨어진다.",
