      "scenario": "70세 남자 환자가 지난 수 일 동안 호흡곤란이 증가하여 내원하였다. 만성폐쇄성폐질환(COPD)과 관상동맥질환이 있으며, 최근에는 고혈압을 진단받았다. 검진상 경정맥 확장은 없었고, 약간의 가슴 전후경 증가가 있으며, 가래 있는 기침은 없다. 청진에서 양측 폐에 호기성 천명음이 들리고 흉통은 없다. 활력징후는 맥박 72회/분, 호흡수 34회/분, 혈압 170/100mmHg이다. 현재 투약은 매 6시간마다 ipratropium(Atrovent, 항콜린제) 흡입, 니트로글리세린 패취, 인데랄(propranolol) 60mg PO bid이다.",
