          "answer": "① 변경이 필요한 약물 — 인데랄(propranolol) 60mg PO bid이다. ② 이유 — propranolol은 비선택적 베타차단제로, 기관지 평활근의 베타2 수용체까지 차단하여 기관지를 수축시키고 만성 폐질환을 악화시킨다. 이 환자는 COPD가 있고 현재 호흡수 34회/분, 양측 호기성 천명음으로 기류 제한이 뚜렷한 상태이므로, 비선택적 베타차단제는 호흡곤란을 더 악화시킬 수 있다. ③ 대체 방안 — 인데랄을 중단하고 항고혈압제로 칼슘채널차단제를 고려한다(예: 베라파밀 80mg PO tid). 칼슘채널차단제는 기관지를 수축시키지 않으면서 혈압을 낮추고, 관상동맥질환에도 사용할 수 있어 이 환자의 동반질환 조합에 적합하다. ④ 유지하는 약물의 근거 — ipratropium(Atrovent) 흡입은 부교감신경을 차단하여 기관지 평활근을 이완시키는 항콜린성 기관지확장제로, 현재의 기류 제한 치료에 필요하므로 유지한다. 니트로글리세린 패취는 관상동맥질환의 예방적 항협심증 약물로, 현재 흉통이 없더라도 유지 목적의 지속형 제제이므로 굳이 설하정으로 바꿀 이유가 없다(설하정은 급성 흉통 발작 시 사용하는 제형이다). ⑤ 추가하지 않아야 할 것 — 이뇨제는 경정맥 확장이 없고 심부전을 시사하는 소견이 없으므로 현 단계에서 우선순위가 아니다. Beclovent(흡입 스테로이드)로 ipratropium을 대체하는 것도 적절하지 않은데, 흡입 스테로이드는 항염증 유지 약물이지 기관지확장제를 대신할 수 없기 때문이다. ⑥ 변경 후 관찰 — 혈압, 맥박, 호흡수, 천명음, 흉통 유무를 함께 추적하고 베타차단제 중단에 따른 협심증 증상 변화를 관찰한다.",
