          "answer": "① 호흡법 — 입술 오므리기 호흡(코로 2초간 들이쉬고 촛불을 끄듯 입술을 오므려 4~6초간 천천히 내쉰다)과 횡격막(복식) 호흡을 매일 연습하게 한다. 기도 내 압력을 유지해 소기도 허탈을 막아 갇힌 공기를 빼내고 호흡곤란을 줄인다. ② 흡입기 사용법 — ipratropium 흡입기를 흔든 뒤 숨을 내쉬고 입에 물고 분사와 동시에 천천히 깊게 들이마신 후 10초간 숨을 참게 하며, 두 번 이상 흡입할 때는 1분 간격을 둔다. 손 힘이나 협응이 부족하면 스페이서를 사용하고, 기관지확장제를 먼저 흡입한 뒤 스테로이드를 흡입하며 사용 후에는 입을 헹구도록 교육한다. 되돌려 시범(teach-back)으로 확인한다. ③ 약물 교육 — 처방된 약을 임의로 중단하거나 용량을 바꾸지 않게 하고, 특히 다른 병원에서 베타차단제 계열 약(안약 포함)을 처방받을 때는 COPD가 있음을 반드시 알리도록 교육한다. 니트로글리세린 패취는 정해진 부위에 매일 바꿔 붙이고, 흉통이 생기면 즉시 알리게 한다. ④ 금연과 환경 관리 — 금연은 COPD의 진행을 늦추는 유일한 방법임을 설명하고 금연클리닉을 연계하며, 가족의 실내 흡연도 금하게 한다. 실내 습도 40~60%를 유지하고 찬 공기·미세먼지·연기·강한 냄새를 피하며 외출 시 마스크를 착용하게 한다. ⑤ 예방접종 — 인플루엔자 백신을 매년 1회, 폐렴구균 백신을 65세 이후 접종하도록 안내한다. 호흡기 감염은 COPD 급성 악화의 가장 흔한 유발 요인이다. ⑥ 에너지 절약과 영양 — 앉아서 세면·옷 입기, 자주 쓰는 물건을 허리 높이에 두기, 무거운 물건은 들지 말고 밀기, 일을 나누어 중간중간 쉬기를 교육하고, 소량씩 자주(하루 5~6회) 고단백·고열량으로 먹으며 가스가 차는 음식과 과식을 피하고 체중을 주 1~2회 기록하게 한다. ⑦ 악화 징후와 대처 — 숨참이 평소보다 심해지거나, 가래의 양이 늘고 색이 누렇거나 초록으로 변하거나, 38℃ 이상 발열, 가슴 답답함, 발목 부종, 의식이 흐려지거나 입술·손톱이 파래지면 즉시 병원에 연락하도록 하고, 혈압 자가측정과 기록을 병행하게 한다.",
