          "answer": "① 의심되는 문제는 기립성 저혈압(체위성 저혈압)이다. ② 진단 근거는 체위 변경에 따른 혈압 하강이다. 앉은 자세에서 130/70mmHg였던 혈압이 선 자세에서 100/60mmHg로 떨어져 수축기혈압이 30mmHg, 이완기혈압이 10mmHg 하강하였다. 기립성 저혈압의 진단 기준은 체위를 바꾼 뒤 3분 이내에 수축기혈압이 20mmHg 이상 또는 이완기혈압이 10mmHg 이상 하강하는 것이므로 이 환자는 두 기준을 모두 충족한다. ③ 발생 기전은 다음과 같다. 정상적으로는 기립 시 하지와 복부 정맥에 혈액이 고여 정맥 환류와 심박출량이 줄어들면 경동맥동과 대동맥궁의 압수용체가 이를 감지하여 교감신경을 항진시키고 심박수 증가와 말초혈관 수축으로 혈압을 유지한다. 노인은 압수용체 반사가 둔해지고 혈관 탄성과 신장의 나트륨 보존 능력이 떨어져 이 보상 기전이 약하다. ④ 여기에 치료 중인 고혈압, 즉 복용 중인 항고혈압제가 결정적으로 작용한다. metoprolol은 베타차단제로 기립 시 필요한 심박수 증가 반응을 차단하고, Captopril은 안지오텐신전환효소(ACE) 억제제로 말초혈관 수축을 막아 보상 기전을 이중으로 차단한다. 여기에 필요시 사용하는 니트로글리세린은 정맥을 확장시켜 정맥 환류를 더 줄인다. ⑤ 그 결과 기립 시 뇌 관류압이 급격히 떨어져 어지럼증이 생기고, 뇌혈류가 더 감소하면 일과성 의식소실(실신)로 이어진다. ⑥ 감별 진단으로 체액량 부족, 부정맥, 심부전을 고려할 수 있으나 신체검진과 심전도, 일반혈액검사, 화학검사, 소변검사가 모두 정상이므로 배제되며, 원인 불명이 아니라 항고혈압 약물 치료라는 명확한 관련 요인이 있다.",
