          "answer": "① 판단: 급성 심근경색증의 가능성이 있다. ② 근거는 다음과 같다. 협심증의 흉통은 대개 안정을 취하거나 니트로글리세린 설하 투여로 수 분 내에 완화되지만, 이 환자는 5분 간격으로 3회 투여한 뒤 30분이 지나도 통증이 줄지 않았다. 니트로글리세린에 반응하지 않고 30분 이상 지속되는 흉통은 관상동맥이 완전히 막혀 심근 괴사가 진행 중임을 시사한다. 여기에 발한, 오심, 구토라는 자율신경 증상이 동반된 것은 급성 심근경색증의 전형적 소견이다. 따라서 불안이나 심리적 원인에 의한 비심인성 통증, 단순한 협심증 악화로 보아 니트로글리세린을 더 투여하며 기다리는 것은 옳지 않고, 즉시 119에 연락하여 응급실로 이송해야 한다. ③ 노인 심근경색증 증상의 특징: 첫째, 환자가 증상을 빨리 느끼지 못한다. 통증 역치가 높아지고 당뇨성 신경병증 등이 동반되어 협심증 증상을 제때 인지하지 못하는 경우가 많으며, 이 때문에 65세 이상의 3분의 2가 증상 발현 후 6시간 이내에 응급실에 도착하지 못한다. 둘째, 심한 흉통이 없는 경우가 많다. 무통성 또는 경미한 불편감으로 나타난다. 셋째, 전형적인 심장 증상 대신 매우 다양한 비전형 증상으로 나타난다. 호흡곤란, 발한, 피로, 심계항진, 실신, 그리고 이 환자처럼 소화가 안 되는 느낌이나 오심·구토 같은 위장관 증상으로 표현되어 소화기 질환으로 오인되기 쉽다. 넷째, 니트로글리세린으로 조절되지 않는다. 협심증과 달리 안정이나 니트로글리세린으로 완화되지 않고 통증 지속시간이 길다. ④ 따라서 노인에게서 원인이 분명하지 않은 소화불량, 갑작스러운 호흡곤란, 발한, 실신이 나타나면 심근경색증을 우선 의심하고 심전도와 심근효소를 확인해야 한다.",
