          "answer": "① 심첨박동의 좌하방 이동 — 정상 심첨박동은 좌측 5번째 늑간의 쇄골중앙선에서 촉지된다. 이것이 좌하방으로 이동했다는 것은 좌심실이 비대해지고 확장되어 심장의 크기가 커졌음을 의미한다. 즉 오랜 압력 부하나 용적 부하에 대한 좌심실의 구조적 재형성이 진행되었다는 소견이다. ② 하지 요흔성 부종(grade 2) — 손가락으로 누르면 자국이 남는 함요부종은 정수압 상승으로 혈관 내 수분이 간질로 이동한 결과이며, 우심 기능 저하와 나트륨·수분 저류에 의한 체액 과부하를 의미한다. 중력의 영향으로 발등과 발목 등 하지에 먼저 나타나며, 와상 환자에서는 천골부에 나타난다. ③ 제3심음(S3) — 확장기 초기에 심실로 혈액이 급속히 유입될 때 이미 확장되고 유순도가 떨어진 심실 벽이 진동하며 생기는 소리로, 심실 충만 이상과 용적 과부하를 시사한다. 젊은 사람에게는 정상일 수 있으나 노인에게서 새로 들리면 심부전의 대표적 징후이다. ④ 진단: 이 세 소견은 모두 심부전에서 나타나는 전형적 징후이므로 가능한 진단은 심부전이다. ⑤ 감별: 폐부종은 심부전의 결과로 나타나는 상태이며 이 환자의 주 소견은 전신 체액 저류이다. 허혈성 심장질환은 흉통과 심전도 변화가 주소견이고, 만성폐쇄성폐질환(COPD)은 호기 연장과 천명이 특징적이며 심첨박동 이동이나 제3심음을 설명하지 못한다. 심장판막질환은 심잡음이 주된 소견이다. ⑥ 따라서 좌심실 비대와 체액 과부하, 심실 충만 이상이 함께 확인되는 이 환자는 심부전으로 판단하고, 원인 질환과 중증도를 밝히기 위한 추가 검사를 시행한다.",
