          "answer": "① BNP(brain natriuretic peptide, 뇌나트륨이뇨펩티드) 또는 NT-proBNP — 심부전 진단에 흔히 사용되는 혈중 검사이다. BNP는 심실 벽이 늘어날 때 심실에서 분비되는 물질이므로 혈중 농도가 오르면 심실에 용적·압력 부하가 걸려 있음을 뜻한다. 호흡곤란의 원인이 심부전인지 폐질환인지 감별하는 데 유용하고, 수치의 높이가 심부전의 중증도와 대체로 비례하며, 치료 후 감소 여부로 반응을 판정하고 이후 추적관찰에도 이용된다. 반면 electrolyte, creatinine, albumin은 심부전을 진단하는 검사가 아니라 동반 문제와 신기능·영양 상태를 보는 검사이고, troponin T는 심근 괴사, 즉 심근경색을 확인하는 검사이다. ② 심초음파 — 좌심실 구혈률(EF, 정상 55% 이상)과 심실 벽 운동, 판막 기능, 심실 비대를 평가하여 수축기 심부전과 이완기 심부전을 구분하고 원인 질환을 규명하기 위함이다. ③ 심전도 — 심방세동 등 부정맥, 좌심실 비대, 과거 심근경색의 흔적과 허혈성 변화를 확인하여 심부전의 원인과 유발요인을 찾기 위함이다. ④ 흉부 방사선검사 — 심비대(심흉비 0.5 초과)와 폐 울혈·폐부종, 흉수를 확인하고 호흡곤란을 일으키는 폐질환을 감별하기 위함이다. ⑤ 전해질과 신기능검사(나트륨·칼륨·혈액요소질소·크레아티닌) — 심부전으로 인한 신관류 저하와 이뇨제 사용에 따른 저칼륨혈증·저나트륨혈증을 확인하기 위함이다. 칼륨 이상은 치명적 부정맥과 디곡신 독성으로 이어지므로 특히 중요하다. ⑥ 전혈구계산과 갑상선기능검사 — 심박출량을 악화시키는 빈혈과, 심부전을 유발·악화시키는 갑상선기능 이상을 확인하기 위함이다. ⑦ 매일 같은 시간의 체중 측정과 섭취량·배설량 기록, 산소포화도 감시 — 체액 저류의 변화를 추적하는 가장 기본적이고 예민한 감시 항목이다.",
