          "answer": "① 심방조기수축(PAC) — 동방결절이 아닌 심방의 이소성 부위에서 예정보다 이른 흥분이 발생하여 나타나는 부정맥으로, 노인에게 흔히 발생하는 양성 부정맥이다. 연령이 증가할수록 빈도가 늘어나지만 기질적 심장질환이 없는 경우 임상적 의미가 크지 않고 대부분 특별한 치료가 필요하지 않다. 따라서 우연히 발견되었다고 해서 즉시 심전도 모니터를 시작하거나 산소를 연결하거나 심박동기 전문의에게 의뢰하거나 제세동기를 준비해 둘 필요는 없으며, 특별한 처치 없이 관찰하는 것이 적절한 간호이다. 다만 카페인·음주·흡연·수면부족·스트레스 등 유발요인을 줄이도록 하고, 심계항진이 잦아지거나 어지럼·실신·호흡곤란이 동반되면 보고하도록 교육하며 정기적인 심전도 추적을 계획한다. ② 조기심실수축(PVC) — 심실의 이소성 초점에서 조기 흥분이 발생하는 부정맥으로, 드물게 나타나면 큰 의미가 없으나 이 환자처럼 빈도가 분당 3회에서 5회로 증가하거나 연속으로 나타나면 주의해야 한다. 그 이유는 심실의 전기적 불안정성을 의미하며 치명적인 심실빈맥이나 심실세동으로 진행할 위험이 있기 때문이다. 심실세동으로 진행하면 곧바로 심정지에 이르므로 조기 발견이 중요하다. ③ 조기심실수축 증가 시 간호: 심전도 감시를 지속하며 PVC의 빈도·형태·연속 여부(2연발·3연발, 다형성 여부, R-on-T 현상)를 기록하고, 활력징후와 맥박 결손, 어지럼·실신·흉통·호흡곤란 등 심박출량 감소 증상을 사정한다. 산소포화도를 확인하고 처방에 따라 산소를 공급하며, 저칼륨혈증·저마그네슘혈증 등 전해질 이상과 디곡신 독성, 저산소증, 카페인·음주 같은 유발요인을 확인해 교정한다. 즉시 의료진에게 보고하고 응급 상황에 대비해 제세동기와 응급 약물을 준비하며, 환자를 안정시키고 활동을 제한한다.",
