      "scenario": "83세 김씨 노인. 재가에서 간병인의 돌봄을 받고 있다. 오늘 간병인이 노인전문간호사에게 \"여러 날 동안 변을 보지 못하다가 어제부터 소변 색 같은 묽은 변을 조금씩 본다\"고 호소하였다. 대상자는 1개월 이상 변비로 완하제를 복용해 오고 있다. 과거력으로 복통과 함께 변비와 설사를 반복하는 배변양상의 변화가 있어 과민성 대장 증후군으로 진단받은 바 있다. 최근에는 활동량이 줄어 대부분의 시간을 앉거나 누워서 지내며, 식사량과 물 마시는 양이 함께 줄었다. 간병인은 설사가 계속되자 지사제를 사다 먹여야 하는지 묻고 있다.",
