          "answer": "① 반드시 포함시켜야 할 항목은 전해질 상태의 확인이다. 완하제를 장기간 복용하면 설사와 배변 횟수 증가로 수분과 전해질이 함께 소실되어 전해질 불균형, 특히 저칼륨혈증이 초래된다. 저칼륨혈증은 근력 약화, 부정맥, 장운동 저하를 일으키고 장운동이 더 떨어지면 변비가 악화되어 완하제를 더 쓰게 되는 악순환을 만든다. 따라서 혈청 칼륨·나트륨·마그네슘·칼슘과 신기능, 섭취량과 배설량, 체중, 탈수 징후(피부 긴장도, 구강 점막 건조, 기립성 저혈압)를 정기적으로 사정한다. 약물간호는 다음과 같다. ② 비약물 중재를 먼저 시도한다 — 수분·식이섬유 증량, 활동량 증가, 규칙적인 배변 습관을 먼저 적용하고, 효과가 없을 때 팽창성 → 삼투성 → 자극성 순으로 단계적으로 사용한다. ③ 팽창성 완하제(차전자피, 메틸셀룰로오스)는 변의 부피를 늘려 자연스러운 연동운동을 유도하므로 1차로 권하되, 반드시 충분한 물과 함께 복용해야 하며 물을 적게 마시거나 와상·장폐색 위험이 있는 노인에게는 오히려 막힐 수 있어 피한다. 효과는 2~3일 후 나타난다. ④ 삼투성 완하제(락툴로오스, 폴리에틸렌글리콜, 산화마그네슘)는 장으로 수분을 끌어와 변을 무르게 하며 노인 만성 변비의 장기 사용에 비교적 안전하다. 다만 복부 팽만·방귀가 있을 수 있고, 마그네슘 제제는 신기능이 저하된 노인에서 고마그네슘혈증(기면·서맥·저혈압)을 유발할 수 있어 주의한다. ⑤ 자극성 완하제(비사코딜, 센나)는 효과가 빠르지만 복통과 전해질 소실이 있고 장기간 남용하면 장이 무력해지므로 단기간·간헐적으로만 사용한다. ⑥ 분변매복이 확인된 경우에는 관장이나 경구 완하제보다 먼저 손가락으로 변 덩어리를 부수어 제거하는 처치를 시행하며, 이때 지사제 투여는 금기다. ⑦ 관장은 좌측 심스위에서 시행하고, 노인은 장천공과 전해질 이상의 위험이 있으므로 비눗물 관장과 반복 관장을 피한다. ⑧ 변비 유발 약물을 재검토한다. 특히 마약성 진통제는 변비에 내성이 생기지 않으므로 투여를 시작하는 시점부터 대변연화제와 자극성 완하제를 함께 처방해 예방한다.",
