          "answer": "① 배변 습관을 만들도록 교육한다 — 매일 같은 시간, 특히 위-대장 반사가 가장 활발한 아침 식후 30분 이내에 변의가 없어도 화장실에 5~10분 앉게 하고, 변의가 있으면 참지 않도록 하며 프라이버시를 확보한다. ② 수분 섭취를 교육한다 — 심부전·신부전으로 제한이 없다면 하루 1,500~2,000mL를 마시게 하고, 아침 기상 직후 미지근한 물 한 컵이 장운동을 자극한다는 점, 실금이 걱정되어 물을 줄이면 변비가 더 심해진다는 점을 설명한다. ③ 식이섬유 섭취를 교육한다 — 채소·해조류·통곡물·자두(프룬)주스·발효유로 하루 20~25g을 섭취하되, 씹기 어려우면 잘게 썰거나 갈아서 제공하고 섬유질을 늘릴 때는 반드시 수분도 함께 늘려야 한다고 강조한다. ④ 활동을 늘리도록 교육한다 — 매일 20~30분 걷기, 앉아서 다리 들기, 침상에서 무릎을 가슴 쪽으로 당기기와 골반 들기, 복식호흡을 하도록 한다. ⑤ 복부마사지와 배변 자세를 시범 교육한다 — 오른쪽 아랫배에서 시작해 위로, 배꼽 위를 가로질러 왼쪽으로, 다시 왼쪽 아랫배로 내려오는 시계 방향으로 하루 2회 10분씩 부드럽게 문지르고, 배변 시에는 발판을 밟아 무릎이 엉덩이보다 높게 오도록 한다. 단, 과도하게 힘주기(발살바 수기)는 혈압 상승과 부정맥을 유발하므로 피하게 한다. ⑥ 약물 사용을 교육한다 — 완하제는 반드시 처방대로 사용하고 임의로 사서 매일 자극성 완하제를 쓰지 않도록 하며, 특히 이번처럼 묽은 변이 나온다고 해서 임의로 지사제를 사다 먹이면 분변매복이 악화된다는 점을 분명히 설명한다. ⑦ 즉시 알려야 할 상황은 3일 이상 변을 보지 못할 때, 여러 날 무배변 후 묽은 변만 조금씩 새어 나올 때(분변매복 신호), 복통·구토·복부 팽만이 있거나 가스와 변이 전혀 나오지 않을 때(장폐색 의심), 혈변이나 검은 변이 보일 때, 식사와 물 섭취가 눈에 띄게 줄거나 처지고 기운이 없을 때(탈수·전해질 이상)이다.",
