          "answer": "① 가장 먼저 확인해야 할 약물은 아세트아미노펜(acetaminophen)이다. 아세트아미노펜은 장기간 복용하거나 용량이 누적되면 용량 의존적으로 간독성을 일으킨다. 간에서 대사되는 과정에서 생성되는 독성 대사산물이 글루타티온으로 해독되는데, 만성 복용·음주·영양불량 상태에서는 글루타티온이 고갈되어 간세포 괴사가 일어난다. 복수와 황달은 간기능 저하와 문맥압항진을 시사하는 소견이므로, 간독성을 유발하는 약물의 복용 여부를 우선 확인해야 한다. 특히 노인은 여러 진통제를 처방 없이 사서 복용하고 복합감기약에도 아세트아미노펜이 들어 있어 자신도 모르게 중복 복용하는 일이 흔하므로, 처방약뿐 아니라 일반의약품과 건강기능식품까지 모두 모아 확인한다. ② 간에서 대사되거나 간의 약물대사효소에 영향을 주어 노인에서 특히 주의해야 하는 약물군은 알코올, 항정신병약제, 신경안정제(벤조디아제핀 등), 항구토제 등이다. 노인은 간 혈류량과 간 용적, 초회통과대사와 약물대사효소 활성이 모두 감소해 있어 같은 용량에도 혈중 농도가 높아지고 반감기가 길어져 효과 증강과 독성이 나타나기 쉽다. 여기에 간경변으로 간기능이 더 떨어지면 진정 작용이 축적되어 간성뇌증을 악화시킬 수 있으므로 진정제·항정신병약제는 최소 용량으로 신중히 사용한다. ③ 반면 강심제(디곡신 등)는 주로 신장으로 배설되므로 간 대사작용에 미치는 영향은 적다. 다만 노인은 신기능도 함께 저하되어 있어 신배설 약물은 신기능(사구체여과율)에 따른 용량 조절과 혈중 농도 감시가 필요하다. ④ 따라서 간질환 노인의 약물간호는 '간독성 약물의 확인과 중단 → 간대사 약물의 용량 조절 → 신배설 약물의 신기능 기준 조절 → 정기적인 간기능검사(AST·ALT·빌리루빈·알부민·프로트롬빈시간) 추적'의 순서로 접근한다.",
