          "answer": "① 락툴로스(lactulose)는 흡수되지 않는 이당류로, 대장에서 장내세균에 의해 분해되면서 장 내용물을 산성화하여 암모니아(NH3)를 흡수되지 않는 암모늄(NH4+)으로 바꾸어 변으로 배설시키고, 동시에 삼투압으로 장으로 수분을 끌어와 변을 무르게 해 배변을 촉진한다. 즉 암모니아 배설을 촉진하고 변비를 완화하는 두 가지 작용으로 간성뇌증을 치료한다. ② 따라서 교육의 핵심은 다음과 같다. 첫째, 증상이 없거나 불편하지 않더라도 처방된 대로 매일 규칙적으로 복용해야 한다. 락툴로스는 필요할 때만 먹는 약이 아니라 암모니아가 쌓이지 않도록 유지하는 약이다. 둘째, 하루 2~3회의 무른 변이 나오는 정도로 용량을 맞추며, 임의로 한꺼번에 많이 복용하면 설사가 심해져 탈수와 저칼륨혈증·저나트륨혈증이 생기고 오히려 간성뇌증이 악화된다. 셋째, 쓴맛이 강해 복용을 거르기 쉬우므로 사과주스나 과일주스, 물에 섞어 마시면 순응도를 높일 수 있다. 넷째, 하루 배변 횟수와 변의 양상, 의식 수준과 지남력, 손 떨림(고정자세불능증, asterixis)의 변화를 기록해 오도록 하고, 설사가 심하거나 변을 전혀 못 볼 때는 임의로 조절하지 말고 알리도록 한다. 다섯째, 탈수 예방을 위해 수분을 적절히 섭취하되 복수와 부종이 있으므로 나트륨 제한과 처방된 수분 제한 범위를 함께 지키게 하고, 체중과 복부둘레를 매일 같은 조건에서 측정하도록 한다. ③ 올바로 이해한 진술은 \"이 약을 사과주스와 함께 복용한다\"이다. 쓴맛을 가려 복용 순응도를 높이는 적절한 방법이다. ④ 잘못 이해한 진술은 다음과 같다. \"불편할 때만 복용한다\" — 증상 유무와 관계없이 규칙적으로 복용해야 한다. \"빨리 낫고 싶어 한꺼번에 많이 복용한다\" — 과량 복용은 심한 설사와 탈수·전해질 불균형을 초래한다. \"변완화제와 함께 복용한다\" — 락툴로스 자체가 배변을 촉진하므로 완하제를 임의로 더하면 설사와 전해질 소실이 심해진다. \"Maalox(제산제)와 함께 복용한다\" — 제산제는 장 내용물의 산성도를 바꾸어 락툴로스의 작용을 방해할 수 있으므로 임의로 함께 복용하지 않는다.",
