          "q": "이 대상자에게 권장할 골다공증 예방 행동 5가지를 근거와 함께 서술하시오.",
          "answer": "① 규칙적인 체중 부하 운동을 시행한다 — 골다공증은 유전적 요인의 영향도 받지만, 걷기·계단 오르기·가벼운 근력운동처럼 체중이 뼈에 실리는 운동은 골밀도를 유지·증가시켜 예방과 치료에 가장 중요한 행동이므로 주 3회 이상, 한 번에 30분 내외로 규칙적으로 하도록 교육한다. ② 칼슘을 권장량에 맞추어 충분히 섭취한다 — 하루 500mg의 칼슘 섭취는 노인의 권장량에 미치지 못하는 양이므로, 우유·요구르트·두부·멸치·녹색 잎채소 등으로 섭취를 늘리고 식이로 부족하면 보충제를 나누어 복용하도록 한다. ③ 비타민D를 함께 보충하고 하루 15~20분 정도 햇빛을 쬐도록 한다 — 비타민D가 부족하면 섭취한 칼슘이 장에서 흡수되지 않아 칼슘 섭취만으로는 효과가 없다. ④ 단백질은 적정량만 섭취한다 — 단백질 식품을 무조건 늘리는 것은 예방 행동이 아니며, 과도한 단백질 섭취는 소변으로의 칼슘 배설을 늘려 오히려 골 소실을 악화시킬 수 있다. ⑤ 음주를 삼가고 금연한다 — '식사 시 적당량의 알코올'은 뼈에 이로운 습관이 아니라 골 소실을 악화시키는 요인이며, 흡연도 골밀도를 낮추고 골절 위험을 높인다. ⑥ 저체중을 피하고 적정 체중을 유지한다 — 저체중은 골밀도를 낮추는 위험요인이므로 체중을 일부러 낮게 유지하는 것은 예방 행동이 될 수 없다. ⑦ 낙상을 예방한다 — 골다공증은 그 자체로는 증상이 없고 골절로 처음 드러나므로, 균형 운동과 집안 환경 정비(문턱 제거, 욕실 손잡이, 야간 조명)를 병행하도록 교육한다.",
