          "answer": "① 개념 — 대상포진 후 신경통(postherpetic neuralgia, PHN)은 피부 발진이 아물고 딱지가 떨어진 뒤에도 침범된 피부분절을 따라 통증이 지속되는 상태를 말한다. 통상 발진 발생 후 3개월(90일) 이상 통증이 남는 경우로 정의하며, 타는 듯한 작열통, 찌르는 듯한 발작통, 옷깃이 스치는 정도의 자극에도 통증을 느끼는 이질통(allodynia), 감각 저하와 저림이 함께 나타난다. 이 대상자처럼 급성기부터 통증으로 잠을 자지 못하는 경우 통증이 만성화되기 쉽다. ② 위험요인 — 고령(나이가 많을수록 발생률과 지속기간이 뚜렷이 증가), 급성기 통증이 심한 경우, 발진이 광범위하거나 심한 경우, 발진 전 전구통이 심했던 경우, 면역저하 상태와 당뇨 등 기저질환, 항바이러스제 투여가 늦어진 경우가 대표적이다. ③ 예방 — 가장 확실한 예방은 발진 후 가능한 한 빨리(보통 72시간 이내) 항바이러스제를 투여하는 것이며, 급성기 통증을 적극적으로 조절하여 통증 신호가 중추에 각인되지 않게 하는 것이 중요하다. 대상포진 예방접종은 대상포진 자체와 대상포진 후 신경통의 발생을 줄여 주므로 접종 대상 여부를 의료진과 상의한다. ④ 약물 관리 — 신경병증성 통증에 준하여 가바펜틴·프레가발린 같은 항경련제, 아미트리프틸린 등 삼환계 항우울제, 국소 리도카인 패치나 캡사이신 제제를 사용한다. 노인에서는 모두 소량으로 시작해 천천히 증량하고(start low, go slow), 어지럼·진정·부종·항콜린 부작용과 그로 인한 낙상 위험을 관찰한다. 단순 진통제만으로는 조절되지 않는 경우가 많으며, 난치성 통증은 통증클리닉의 신경차단술 등을 의뢰한다. ⑤ 간호중재 — 통증을 숫자통증등급(NRS)으로 정기적으로 사정하고 수면·식욕·기분·활동량의 변화를 함께 확인한다. 만성 통증은 우울과 사회적 고립, 활동 저하로 이어지므로 노인우울척도로 우울을 선별하고 정서적 지지와 사회활동 참여를 격려한다. 옷이 스치는 자극을 줄이도록 부드럽고 헐렁한 옷을 입게 하고, 이완요법·주의전환·규칙적인 활동으로 통증 대처를 돕는다.",
