          "answer": "① 첫 번째 증상군 — '지난 2년 동안 점점 시야가 흐려지며 통증은 없다'는 호소는 수정체가 서서히 혼탁해지는 백내장의 전형적인 양상이다. 백내장은 수년에 걸쳐 서서히 진행하는 무통성 시력 저하가 특징이며, 그 밖에 점진적 시력저하, 한쪽 눈으로도 사물이 둘로 보이는 복시, 빛이 번져 보이는 눈부심, 색 대비 감소, 밝은 곳에서 오히려 잘 안 보임 등이 나타난다. 감별할 질환으로 급성 폐쇄각 녹내장은 심한 안통·두통·구토·충혈을 동반하고, 망막박리는 갑작스러운 비문증·광시증과 커튼이 내려오는 듯한 시야 결손을 보이며, 황반변성은 중심시야의 왜곡과 암점이 주 증상이고, 안구건조증은 이물감·작열감이 주 증상이므로 이 대상자의 무통성 점진적 시야 흐림과는 양상이 다르다. ② 두 번째 증상군 — '빛에 대한 민감성 증가, 어둠에 적응하는 데 어려움(암순응 저하), 깊이에 대한 인지 변화'는 노화에 따른 정상적인 눈의 변화로 흔히 나타나는 소견이다. 나이가 들면 동공이 작아지고 동공반응이 느려지며 수정체가 두꺼워지고 황변화되어 들어오는 빛의 양이 줄고 산란이 늘어나, 눈부심이 심해지고 밝은 곳에서 어두운 곳으로 옮길 때 적응이 오래 걸린다. 또한 조절력과 양안 시기능이 저하되어 거리·깊이 지각이 달라진다. 이는 특정 안질환의 병적 소견이 아니므로 질병으로 오인해 불필요한 검사를 하기보다 정상 노화 변화임을 설명하고 안전 중재를 적용한다. ③ 임상적 의미 — 두 증상군이 겹치면 야간과 어두운 복도에서의 낙상 위험이 크게 높아진다. 눈부심을 줄이도록 간접 조명과 눈부심 방지 조명을 쓰고, 밝은 곳과 어두운 곳을 오갈 때 적응할 시간을 주며, 계단 끝과 단차에 대비되는 색 표시를 하고, 야간 조명을 상시 켜 두며, 정기적인 시력검사와 안경 도수 조정을 시행한다.",
