          "answer": "① 안압측정(tonometry) — 녹내장 진단에서 가장 중요한 근거가 되는 검사이다. 정상 안압은 10~21mmHg이며 녹내장에서는 23mmHg 이상으로 상승한다. 방수의 생성과 배출 균형이 깨져 안압이 올라가면 시신경이 압박되어 손상되므로, 안압을 측정하여 진단하고 치료 목표 안압을 정하며 약물 반응을 추적한다. ② 우각경 검사(gonioscopy) — 각막과 홍채 사이의 우각(전방각)을 직접 관찰하여 각이 넓은지 좁은지 조사하는 검사이다. 이를 통해 개방각 녹내장과 폐쇄각 녹내장을 감별하며, 이 감별에 따라 치료 방침(약물 선택, 레이저 홍채절개술 필요 여부)이 달라진다. 이 대상자는 원발성 개방각 녹내장으로 진단되었다. ③ 시신경 유두 검사(안저검사) — 안저에서 시신경 유두의 모양을 관찰하여 유두 함몰(cupping)의 확대, 유두 창백, 신경섬유층 결손 등 시신경 손상의 구조적 변화를 확인한다. 안압이 정상 범위여도 시신경 손상이 진행하는 정상안압녹내장이 있으므로 반드시 함께 시행하며, 경과 관찰의 기준이 된다. ④ 시야검사(visual field test, perimetry) — 시신경 손상으로 생기는 기능적 결손을 확인하는 검사이다. 녹내장은 주변 시야부터 결손이 생겨 진행하며 말기까지 중심시력이 유지되는 경우가 많으므로, 시야검사로 결손의 범위와 진행 속도를 정량적으로 추적한다. 이 밖에 각막두께 측정과 빛간섭단층촬영(OCT)으로 신경섬유층 두께를 측정하기도 한다. ⑤ 시력검사가 진단검사로 적절하지 않은 이유 — 녹내장은 주변 시야부터 서서히 손상되고 중심시력은 상당히 진행할 때까지 정상으로 유지되기 때문에, 시력검사만으로는 초기 녹내장을 발견할 수 없다. 따라서 녹내장 진단에는 시력검사가 아니라 시야검사를 시행해야 하며, 시력검사는 전반적인 시기능 평가와 백내장 등 동반 질환 확인을 위한 보조 검사로 활용한다.",
