          "answer": "① 금기 약물 — timolol이다. timolol은 비선택적 베타차단제 점안제로, 안구에 점안해도 코눈물관을 통해 전신으로 흡수되어 기관지 평활근의 베타2 수용체를 차단한다. 그 결과 기관지 평활근이 수축하여 기관지 경련과 천식 발작을 유발할 수 있으므로 천식 환자에게는 사용을 금한다. 또한 서맥·저혈압·방실차단을 일으킬 수 있어 서맥성 부정맥이나 조절되지 않는 심부전이 있는 노인에게도 주의해야 하며, 당뇨 환자에서는 저혈당의 경고 증상(빈맥·떨림)을 가려 위험하다. ② 사용 가능한 약물과 기전 — acetazolamide(diamox)는 탄산탈수효소억제제(carbonic anhydrase inhibitor)로 모양체에서 방수의 생성 자체를 줄여 안압을 낮춘다. 전신 투여 시 이뇨·저칼륨혈증·대사성 산증·감각이상·식욕부진이 생길 수 있으므로 전해질과 신기능을 확인한다. ③ pilocarpine은 부교감신경 흥분제(축동제)로 섬모체근(ciliary muscle)을 수축시켜 섬유주(trabecular meshwork)를 열어 줌으로써 방수의 배출을 촉진한다. 동공이 작아져 어두운 곳에서 시야가 더 어두워지고 조절경련으로 두통이 생길 수 있어, 이미 암순응이 떨어진 이 대상자에게는 야간 낙상 위험을 함께 고려해야 한다. ④ latanoprost(Xalatan)는 프로스타글란딘 제제로 포도막공막 경로를 통한 방수 배출을 증대시켜 안압을 낮춘다. 하루 한 번 점안으로 효과가 좋아 흔히 일차 약제로 쓰이며, 홍채·눈꺼풀 색소침착과 속눈썹 길어짐, 결막충혈 같은 국소 부작용을 미리 설명한다. 참고로 Lasix(furosemide)는 전신 이뇨제로 녹내장 치료제가 아니다. ⑤ 간호중재 — 안약은 정해진 시간에 빠뜨리지 않고 점안해야 하며, 임의로 중단하면 시신경 손상이 진행하고 이미 손상된 시야는 회복되지 않음을 교육한다. 점안 방법을 시범으로 가르친다 — 손을 씻고 아래 눈꺼풀을 당겨 결막낭에 한 방울 떨어뜨리고, 용기 끝이 눈에 닿지 않게 하며, 점안 후 눈을 감고 코 안쪽 눈물점을 1~2분간 누르는 비루관 폐쇄를 시행하면 전신 흡수를 줄여 부작용을 예방할 수 있다. 두 가지 이상의 안약은 5분 이상 간격을 두고 넣는다. 시력 저하로 스스로 점안이 어려우면 시설 간호인력이 확인·투약하고, 천식 흡입제와 안약을 함께 관리하며 호흡음·호흡곤란·천명을 관찰한다. 다른 진료과에서 처방받을 때 천식과 녹내장이 있음을 반드시 알리도록 교육한다(항콜린제는 폐쇄각 녹내장에서 주의).",
