          "q": "이 대상자의 노인성 난청을 뒷받침하는 검진 소견을 쓰고, 시설에서 난청을 의심할 수 있는 행동 징후 3가지와 의사소통·안전 중재를 서술하시오.",
          "answer": "① 검진 소견 — 노인성 난청(presbycusis)은 내이의 코르티기관 유모세포와 청신경이 퇴행하여 생기는 고주파 영역의 감각신경성 난청이다. 따라서 Rinne 검사에서 정상 감각신경 청력에서와 마찬가지로 공기전도가 골전도보다 길게(오래) 들리는 Rinne 양성 소견이 유지된다. 이는 소리 전달 경로 자체가 막히는 전도성 난청(만성 중이염·이구전색 등)에서 골전도가 공기전도보다 길어지는 것과 구별되는 핵심 소견이다. Weber 검사에서는 소리가 한쪽으로 치우치지 않거나 청력이 좋은 쪽으로 편위된다. 또한 귀에서 1~2인치 거리의 시계 소리처럼 고주파 소리를 듣지 못하는 것은 고주파 청력 저하를 시사하는 소견이며, 순음청력검사에서 고주파부터 떨어지는 하강형 곡선과 어음변별력 저하(소리는 들리지만 말뜻을 알아듣지 못함)가 확인된다. 반면 장기간의 테트라사이클린 사용력이나 잘 정립된 가족력, 만성 중이염 병력은 노인성 난청의 진단 근거가 아니다. ② 시설에서 난청을 의심할 수 있는 행동 징후 — 첫째, 대화할 때 공격적인 태도를 보인다. 잘 들리지 않아 되묻거나 오해가 생기고, 자신도 모르게 목소리가 커지며 짜증과 의심이 늘어난다. 둘째, 모임을 피하려 한다. 여러 사람이 함께 말하는 자리에서는 알아듣기가 특히 어려워 스스로를 격리시키고 활동에 참여하지 않는다. 셋째, 텔레비전이나 라디오 소리를 지나치게 높인다. 이 밖에 질문에 대한 대답과 말의 반복을 불필요하게 자주 요구하고, 뒤에서 부르면 반응하지 않으며, 엉뚱한 대답을 한다. 참고로 가족과의 전화통화 시간이 길어지는 것은 난청 의심 징후에 해당하지 않는다. ③ 의사소통 중재 — 조용하고 밝은 곳에서 얼굴을 마주 보고 대화하며, 말하기 전에 이름을 부르거나 가볍게 접촉해 주의를 끈다. 소리를 지르지 말고 평소보다 조금 낮은 음조로 또렷하게 천천히 말하며, 같은 말을 반복하기보다 다른 표현으로 바꾸어 말한다. 입 모양이 보이도록 하고 몸짓·표정·필담·그림을 함께 사용하며, 중요한 내용은 글로 적어 주고 이해했는지 되물어 확인한다. 배경 소음(TV·라디오)을 줄이고, 보청기를 사용한다면 착용 상태·건전지·이구 막힘을 매일 점검한다. 정기적인 청력검사와 이구전색 확인도 필요하다. ④ 안전·심리사회적 중재 — 난청은 경고음·호출음·발소리를 놓치게 하고 평형기능 저하와 겹쳐 낙상 위험을 높이므로, 시각적 알림(불빛 호출등·진동 알람)을 사용하고 이동 동선을 밝게 유지한다. 이 대상자는 시력 저하까지 동반되어 있어 위험이 더 크므로 안경·보청기 착용을 함께 확인한다. 의사소통 단절로 인한 우울·사회적 고립·인지 저하를 예방하도록 소규모 활동 참여를 권하고, 공격적 태도를 성격 문제로 보지 않고 난청의 결과로 이해하도록 직원과 가족을 교육한다.",
