      "scenario": "74세 여성. 파킨슨병으로 약물치료를 받아 비교적 잘 조절되어 왔다. 걸음은 동작이 느리고 불안정하며 약간의 뒤로 넘어짐(retropulsion)이 동반된다. 최근 가볍게 넘어진 뒤 또 넘어질 것에 대한 두려움으로 활동량이 감소하였다. 다른 신경학적·근골격적 문제는 없다. 이후 손떨림과 보행 시 어려움이 증가하여 Trihexyphenidyl hydrochloride(트리헥신)를 하루 3mg에서 5mg으로 증량하였고, 간호사는 대상자와 동거 가족에게 증량과 관련한 주의사항을 교육하려 한다.",
