          "q": "Trihexyphenidyl hydrochloride를 하루 3mg에서 5mg으로 증량하였다. 가족에게 교육해야 할 주의사항 5가지를 약리 기전과 함께 서술하시오.",
          "answer": "Trihexyphenidyl은 항콜린성 약물로, 파킨슨병에서 상대적으로 항진된 아세틸콜린 작용을 차단하여 떨림과 약물성 이상운동 증상을 조절하는 보조제로 사용한다. 용량을 올리면 항콜린 작용이 함께 강해지므로 다음을 교육한다. ① 구강건조(구갈) — 침 분비가 줄어 입이 마르고 삼키기 불편해진다. 물을 자주 조금씩 마시고 무설탕 껌·얼음조각을 이용하며 구강간호를 자주 하고 구강 칸디다증과 치아 우식을 관찰한다. ② 시야 흐림과 눈부심 — 동공이 확대되고 조절 기능이 떨어져 가까운 글씨가 흐려 보인다. 이 상태로 계단을 오르내리거나 야간에 혼자 이동하지 않게 하고, 눈 통증·충혈·두통이 생기면 급성 폐쇄각 녹내장 가능성이 있으므로 즉시 병원에 오도록 한다. ③ 변비와 배뇨곤란·요폐 — 위장관과 방광 평활근의 운동이 억제된다. 수분과 섬유질을 충분히 주고 규칙적 배변을 돕되, 소변을 못 보거나 아랫배가 팽만하고 소량씩 자주 흘리듯 나오면 요폐이므로 즉시 알리도록 한다(전립선비대가 있으면 특히 주의). ④ 혼동·기억력 저하·환각 — 노인은 항콜린 부담에 취약하여 증량 후 갑자기 멍해지거나 헛것을 보고 밤에 심해질 수 있다. 이는 섬망일 수 있으므로 '치매가 나빠졌다'고 넘기지 말고 즉시 보고하게 한다. ⑤ 발한 감소로 인한 열 축적 — 땀이 나지 않아 더운 날 체온이 쉽게 오르므로 무더위 노출과 과도한 운동을 피하게 한다. ⑥ 임의 증감·중단 금지 — 정해진 시간에 정확히 복용하고, 부작용이 있어도 스스로 끊지 말고 반드시 의사와 상의하도록 한다. 또한 이 약은 기립성 저혈압과 인지 흐림을 통해 낙상 위험을 높이므로 증량 직후 며칠은 이동 시 동행한다.",
