          "answer": "① 병태생리: 지남력이 있던 대상자가 점차 수면 경향을 보이며 질문에 적절히 답하지 못하는 것은 의식수준의 저하이고, 동공이 고정(fixed)되어 대광반사가 소실된 것은 동안신경이 압박되고 있다는 뜻이다. 뇌경색 부위에 뇌부종이 생기면서 두개내압(ICP)이 상승하고 뇌조직이 밀려나는 탈출(herniation) 직전 상태를 시사하는 응급 징후이다. ② 즉시 시행할 사정: 글래스고 혼수척도(GCS, 눈뜨기 4 + 언어반응 5 + 운동반응 6 = 15점)로 의식을 정량화하고, 양측 동공의 크기·좌우 대칭·대광반사를 반복 확인한다. 활력징후에서 수축기혈압 상승, 서맥, 불규칙한 호흡이라는 쿠싱 삼징(Cushing's triad)이 나타나는지 보고, 사지 근력과 자세(제피질·제뇌 경직), 두통·구토 여부, 산소포화도를 함께 확인한다. ③ 보고: 마지막으로 정상이었던 시각과 변화의 경과, GCS 점수 변화, 동공 소견, 활력징후를 묶어 즉시 의사에게 보고한다. ④ 예상 약물: 삼투성 이뇨제인 mannitol(만니톨)이다. 혈액의 삼투압을 높여 뇌조직의 수분을 혈관 내로 끌어내고 신장으로 배출시켜 뇌부종과 두개내압을 신속히 낮춘다. ⑤ 투여 시 간호: 정맥으로 빠르게 주입하며 결정이 생겼는지 확인하고 필터가 있는 수액세트를 사용한다. 강력한 이뇨가 뒤따르므로 섭취량/배설량, 혈청 전해질과 삼투압, 신기능, 혈압을 감시하여 탈수·저혈압·전해질 불균형을 예방한다. 침상머리는 30도 올리고 머리를 중립위로 유지하며 목의 굴곡·과신전을 피한다. 기침·구토·배변 시 힘주기(발살바)와 불필요한 흡인을 피하고, 흡인이 필요하면 10~15초 이내로 짧게 시행하며 사전 산소화를 한다. 조명·소음 등 자극을 줄이고, 뇌경색이 확인되기 전이나 출혈 가능성이 배제되지 않은 상태에서는 항혈전제를 임의로 투여하지 않는다.",
