          "answer": "① 잘 삼키지 못함 — 음식을 입에 넣고도 삼킴이 시작되지 않거나 여러 번 나누어 삼키며, 삼킨 뒤에도 입 안에 음식이 남는다. ② 목에 음식이 붙어 있는 듯한 느낌을 호소함 — 인두에 잔여물이 남아 이물감을 호소하며 반복해서 헛기침을 한다. ③ 목소리 변화 — 삼킨 뒤 목소리가 잠기거나 젖은 소리(gurgling voice)로 변하는 것은 성대 위에 음식물이나 액체가 고여 있다는 뜻으로 흡인의 강력한 신호다. ④ 삼키는 동안 기침을 함 — 삼킴 도중이나 직후의 기침·사레는 후두 침습과 흡인을 시사한다. 다만 기침이 없어도 흡인이 일어나는 무증상 흡인(silent aspiration)이 있으므로 기침이 없다고 안심하지 않는다. ⑤ 식사 시간의 연장과 섭취량 감소 — 한 끼에 30분 이상 걸리고 먹다가 지쳐 남기며, 체중 감소와 탈수로 이어진다. ⑥ 음식물이 입 밖으로 새어 나옴·침 흘림 — 구강기 장애와 안면 마비를 시사한다. ⑦ 반복되는 발열과 폐렴, 식사 중 산소포화도 저하도 흡인의 간접 증거다. 【검사 방법】 첫째, 경구 섭취 전 침상 물 삼킴검사(bedside water swallow test)로 선별한다 — 소량의 물을 삼키게 한 뒤 기침, 젖은 목소리, 산소포화도 저하를 확인하고 이상이 있으면 금식(NPO)시킨다. 둘째, 확진과 식이 형태 결정을 위해 VFSS(videofluoroscopic swallowing study, 비디오투시연하검사)를 시행하여 흡인 여부와 시점, 안전한 음식 점도를 확인한다. 셋째, 필요 시 내시경적 연하검사(FEES)를 시행하고, 넷째, 구강·안면 근력과 연하반사·구역반사, 인지수준과 자세 유지 능력을 함께 사정하며, 다섯째, 흉부 X선과 체중·알부민 등 영양지표로 흡인성 폐렴과 영양불량을 확인한다.",
