          "answer": "① 경구 섭취 전 연하기능을 선별하고 결과에 따라 식이를 결정한다 — 침상 물 삼킴검사에서 기침·젖은 목소리·산소포화도 저하가 있으면 즉시 금식(NPO)시키고, VFSS 결과에 근거해 안전한 음식 점도와 한 입 크기를 정한다. 매 식사 전 각성 수준을 확인하여 졸려 하거나 반응이 떨어질 때는 먹이지 않는다. ② 식사 자세를 관리한다 — 침상머리를 90도로 올려 똑바로 앉히고 턱을 가슴 쪽으로 당긴 자세(chin-tuck)를 취하게 하여 기도 입구를 좁힌다. 마비가 있으면 건측으로 음식을 넣어 준다. 식후 30분에서 1시간은 앉은 자세를 유지하여 역류와 흡인을 예방한다. ③ 음식의 형태와 제공 방법을 조절한다 — 맑은 물과 미음처럼 묽은 액체가 가장 흡인되기 쉬우므로 점도증진제로 걸쭉하게 만들고, 부드럽게 갈은 음식을 한 번에 티스푼 한 술 정도씩 천천히 제공하며 삼킨 것을 확인한 뒤 다음 숟가락을 준다. 식사 중에는 대화와 TV를 피해 삼킴에 집중하게 하고, 식후에는 마비된 쪽 볼에 음식이 남았는지 확인하고 구강간호를 시행하여 구강 내 세균을 줄인다. ④ 흡인의 조기 징후를 감시하고 응급에 대비한다 — 식사 중 기침, 미열, 가래 증가, 호흡음 이상, 산소포화도 저하를 매 근무조 관찰하고 침상 옆에 흡인 장비와 산소를 준비한다. ⑤ 구강 섭취가 불가능하면 비위관 또는 위루관으로 영양을 공급하되, 주입 전 관의 위치와 위 잔류량을 확인하고 주입 중과 주입 후 30~60분간 상체를 30~45도 이상 올려 둔다.",
