      "title": "[문제집] 전립선비대에 의한 부분 폐색이 의심되는 78세 남성 (당뇨·불안장애·만성폐쇄성폐질환·다약제)",
      "scenario": "78세 남성. 계속되는 빈뇨와 긴박뇨로 요실금을 하여 하루에 1~2회 옷을 갈아입어야 한다고 호소한다. 직장수지검사상 변비의 증거는 없었고, 전립선은 다소 커져 있었으며 부분적 폐색이 의심되었다. 최근에는 소변이 곧바로 나오지 않고 뜸을 들여야 나오며(지연뇨), 배뇨 시 통증과 혈뇨가 간헐적으로 있었다고 한다. 요로감염으로 항생제를 처방받은 적이 여러 차례 있다. 동반질환으로 2형 당뇨(경구 glyburide/Diabeta), 불안장애(경구 buspirone), 만성폐쇄성폐질환(흡입용 ipratropium/Atrovent)이 있고, 전립선비대 치료로 doxazosin(Cardura)을 3주 동안 복용해 왔는데 요즘 앉았다 일어설 때 어지럽다고 호소한다. 담당의는 finasteride(Proscar) 추가를 고려하고 있다.",
