          "q": "이 대상자에게 신부전이 발생한다면 어떤 기전으로 생기는지 신부전의 원인 분류에 따라 설명하고, 남성 노인의 반복적 요로감염에서 흔한 원인과 국소 전립선암에서 나타나는 증상을 함께 서술하시오.",
          "answer": "① 신부전은 원인 부위에 따라 신장전(prerenal), 신장내(intrarenal), 신장후(postrenal) 원인으로 분류한다. 신장전 원인은 신장으로 가는 혈류가 줄어드는 경우로 심한 저혈압을 동반한 심근경색, 출혈, 탈수, 심부전이 해당한다. 신장내 원인은 신실질 자체의 손상으로 오랜 당뇨로 인한 이차적 신장혈관 변화(당뇨병성 신증), carbon tetrachloride 같은 신독성 물질의 장기 노출, 신우신염에 의한 신장 기능 손상, 신독성 약물이 해당한다. 신장후 원인은 신장 원위부, 즉 요관·방광·요도의 폐색으로 소변이 배출되지 못해 생기며 혈뇨를 동반한 전립선비대증, 전립선암, 요로결석, 종양에 의한 요관 압박이 대표적이다. ② 이 대상자는 전립선이 커져 방광출구가 부분적으로 막혀 있고 혈뇨가 동반되어 있으므로 폐색이 진행되면 소변이 방광에 정체되고 압력이 상부요로로 전달되어 수신증이 생기고 사구체여과율이 떨어지는 신장후 신부전으로 이어질 수 있다. 신장후 신부전은 폐색을 해결하면 신기능이 회복될 수 있는 가역적 원인이므로 조기 발견과 감압(도뇨·수술)이 중요하다. ③ 남성 노인의 재발성 요로감염에서 가장 흔한 원인 중 하나는 전립선염이다. 전립선 조직이 세균의 저장소가 되어 항생제로 일시적으로 호전되었다가 반복적으로 재발하며, 여기에 전립선비대에 의한 잔뇨가 더해지면 감염이 더 잘 생긴다. 따라서 남성에서 요로감염이 반복되면 단순 방광염으로 보지 말고 전립선 평가와 잔뇨 측정을 반드시 함께 한다. ④ 국소적 전립선암은 초기에는 무증상인 경우가 많으나 종양이 요도를 압박하면서 전립선비대증과 유사한 하부요로 증상, 즉 지연뇨, 빈뇨, 배뇨통, 잔뇨감, 혈뇨를 호소한다. 체중감소, 심한 빈혈, 뼈 통증 등은 전이가 진행된 단계의 증상이므로 국소암의 증상과 구분해야 한다. 이 대상자처럼 증상만으로는 양성 전립선비대와 구분되지 않으므로 직장수지검사와 PSA, 필요 시 조직검사로 감별한다.",
