          "q": "finasteride(Proscar)를 시작하는 이 대상자와 가족에게 교육할 내용 6가지를 서술하시오.",
          "answer": "① 약물의 작용을 설명한다 — finasteride는 5알파환원효소를 억제하여 테스토스테론이 디하이드로테스토스테론(DHT)으로 전환되는 것을 차단함으로써 전립선의 성장을 억제하고 크기 자체를 줄이는 약이다. 알파차단제(doxazosin)가 평활근을 이완시켜 증상을 빠르게 완화하는 것과 달리, finasteride는 원인이 되는 전립선 크기에 작용하므로 두 약을 함께 쓰면 상호보완적이다. ② 가장 중요한 주의사항으로, 임신부나 가임 여성이 이 약물에 닿지 않도록 교육한다. 부서지거나 깨진 정제를 임신부가 만지면 피부로 흡수되어 남성 태아의 외부생식기 기형을 유발할 수 있으므로, 정제를 쪼개거나 부수지 말고 원래 포장 그대로 보관하며 가족 중 가임 여성이 약을 정리하거나 폐기하지 않도록 한다. 남은 약의 폐기도 가임 여성이 아닌 사람이 처리하고 약국에 반납하는 것이 안전하다. ③ 효과가 나타나기까지 3~6개월이 걸리므로 증상이 금방 좋아지지 않는다고 임의로 중단하지 않도록 교육하고, 반대로 증상이 좋아졌다고 해서 스스로 끊으면 전립선이 다시 커진다는 점을 설명한다. ④ 성욕 감소, 발기부전, 사정량 감소 같은 성기능 관련 부작용과 여성형 유방이 생길 수 있음을 미리 설명하고, 부끄러워하지 말고 의료진에게 알려 조정받도록 한다. ⑤ finasteride를 복용하면 전립선특이항원(PSA) 수치가 약 50% 낮아지므로, 전립선암 선별검사를 받을 때 반드시 이 약을 복용 중이라고 알려 결과가 잘못 해석되지 않도록 교육한다. ⑥ 복용 중에도 배뇨 양상을 계속 관찰하여 소변 줄기가 더 약해지거나 잔뇨감이 심해지는지, 혈뇨·발열·배뇨통이 생기는지 확인하고, 소변이 전혀 나오지 않으면서 아랫배가 팽팽하고 아픈 급성 요폐는 응급 상황이므로 즉시 병원에 오도록 교육한다. ⑦ 함께 복용하는 doxazosin의 기립성 저혈압과 어지럼, 그리고 항콜린 작용이 있는 감기약·수면유도제·1세대 항히스타민제를 임의로 사서 먹지 않도록 교육한다.",
