          "answer": "① 유형 감별: 기침을 하거나 무거운 물건을 들어올릴 때, 즉 복압이 갑자기 올라가는 순간에 소량의 소변이 새는 양상은 전형적인 복압성(스트레스) 요실금이다. 갑작스럽고 참을 수 없는 요의와 함께 다량이 새는 절박성, 소변 줄기가 약하고 찔끔찔끔 계속 새며 잔뇨감이 있는 일류성, 요의는 정상인데 인지·이동 문제로 화장실에 가지 못해 새는 기능성 요실금과 구별된다. 원인은 전립선절제술 과정에서 요도괄약근과 주변 지지조직이 일시적으로 약해진 것이다. ② 최대요속 해석: 최대요속은 배뇨 시 소변이 흐르는 최대 속도로, 남성의 정상 범위는 20~55mL/sec, 여성은 25~30mL/sec이다. 이 대상자의 23mL/sec는 정상 범위에 있으므로 방광출구 폐색이나 요도협착이 없음을 뒷받침한다. 실제로 검사상 요관의 폐쇄나 협착의 증거도 없었다. 즉 배출 장애가 아니라 괄약근 기능의 일시적 저하가 원인임을 객관적으로 확인해 주는 소견이다. ③ 초기 접근: 전립선절제술 후 실금은 수술 후 흔하게 나타나며 시간이 지나면서 대부분 저절로 좋아진다. 따라서 초기 접근으로 가장 적절한 것은 환자를 안심시키고 골반저근운동 등 보존적 치료를 하면서 계속 관찰하는 것이다. 폐색이나 협착이 없고 요속이 정상이므로 알파아드레날린 차단제(Cardura, doxazosin) 같은 전립선비대 치료 약물은 필요하지 않으며, 오히려 기립성 저혈압으로 낙상 위험만 높인다. 하루 3회 간헐적 도뇨는 잔뇨가 문제되는 상황이 아니므로 적응증이 아니고 요로감염 위험만 키운다. 인공 요도조임근 삽입 같은 수술적 치료는 보존적 치료를 6~12개월 이상 충분히 시행한 뒤에도 실금이 지속될 때 고려하는 최후의 방법이다. 다만 실금이 악화되거나 발열·혈뇨·배뇨통·잔뇨감이 생기면 비뇨기과 재평가가 필요함을 함께 설명한다.",
