          "q": "이 대상자에게 시행할 보존적 간호중재 6가지를 서술하시오.",
          "answer": "① 골반저근운동(Kegel, 케겔운동)을 정확한 방법으로 교육한다 — 소변을 참듯 항문 주위 근육만 5~10초간 조였다가 같은 시간 이완하기를 10~15회씩 하루 3세트 시행하고, 배·엉덩이·허벅지에는 힘을 주지 않으며 숨을 참지 않는다. 앉아서·누워서·서서 모두 할 수 있고 효과는 6~8주 후에 나타나므로 최소 3개월 이상 지속하도록 격려한다. 남성은 처음에 올바른 근육을 찾기 어려우므로 배뇨 중 잠깐 소변 줄기를 멈춰 보게 하여 감각을 익히되(연습 방법일 뿐 습관화하지는 않도록 한다), 필요하면 바이오피드백을 이용한다. ② 복압이 올라가는 순간, 즉 기침·재채기·물건을 들어올리기 직전에 미리 골반저근을 조이는 방법(knack 기법)을 반복 연습시킨다. ③ 3일간 배뇨일지를 작성하게 하여 새는 시각과 상황, 배뇨 간격, 패드 사용 수를 기록하게 하고 이를 근거로 정해진 시간에 배뇨하도록 하며 회복 경과를 객관적으로 비교한다. ④ 복압을 높이는 요인을 관리한다 — 체중 감량, 변비 예방을 위한 수분·섬유질 섭취와 규칙적 배변, 금연으로 만성 기침 줄이기, 무거운 물건 들지 않기, 쪼그려 앉아 힘주는 동작 피하기를 교육한다. ⑤ 수분과 음식을 조절한다 — 실금이 두려워 물을 줄이면 소변이 농축되어 방광을 자극하고 요로감염과 변비가 생기므로 하루 1,500~2,000mL를 낮 동안 나눠 마시고 취침 2~3시간 전부터만 줄이며, 카페인·알코올·탄산음료·인공감미료 등 방광 자극 물질을 제한한다. ⑥ 피부 보호와 용품 사용을 교육한다 — 흡수용품은 치료가 아니라 임시 보조수단임을 설명하고 젖는 즉시 교체하며, 실금 후에는 미온수로 씻고 두드려 말린 뒤 배리어 크림을 바르고 파우더는 쓰지 않는다. ⑦ 심리·사회적 지지를 제공한다 — 수술 후 실금은 흔하고 대부분 회복된다는 사실을 설명하여 불안을 덜어 주고, 외출 시 여벌 옷과 용품을 준비하는 실질적인 방법을 함께 계획해 모임을 회피하는 사회적 고립을 예방하며, 배우자와 가족의 이해를 구한다.",
