          "answer": "① 시행하지 않는 이유: 이 대상자는 잔뇨나 요저류가 문제인 것이 아니라 복압 상승 시 괄약근이 버티지 못해 소량이 새는 복압성 요실금이므로, 도뇨관을 넣어도 원인이 해결되지 않는다. 오히려 유치도뇨관은 삽입 기간이 하루 늘어날 때마다 세균뇨 발생이 누적되어 도뇨관 관련 요로감염(CAUTI)의 위험을 크게 높이고, 요도 손상과 협착, 방광 경련, 결석, 활동 제한과 자존감 저하를 초래한다. 게다가 도뇨관에 의존하면 골반저근을 쓰지 않게 되어 자연 회복과 골반저근운동의 효과를 방해한다. 따라서 유치도뇨관은 요실금 관리 수단이 아니라 요저류·요로 폐색·정확한 소변량 측정이 반드시 필요한 경우에 쓰는 최후의 수단이며, 이 대상자에게는 골반저근운동을 포함한 보존적 치료가 우선임을 설명하고 불안을 다룬다. ② 불가피할 때의 간호원칙: 첫째, 삽입은 무균술로 시행하고 대상자의 체격에 맞는 최소 굵기의 도뇨관을 선택하여 요도 손상과 자극을 줄인다. 둘째, 폐쇄배액체계를 유지하고 연결부를 함부로 분리하지 않으며 검체는 지정된 채취구에서 소독 후 채취한다. 셋째, 소변주머니는 항상 방광보다 낮게, 바닥에 닿지 않게 유지하고 이동 시에도 역류되지 않도록 하며 배액관이 꺾이거나 눌리지 않게 한다. 넷째, 회음부와 도뇨관 삽입 부위를 매일 물과 순한 비누로 청결히 하고, 소변의 색·혼탁·냄새·양과 발열·측복통·섬망 등 감염 징후를 관찰하며 수분 섭취를 충분히 유지한다. 다섯째, 도뇨관 유지의 필요성을 매일 재평가하여 필요가 없어지면 즉시 제거하고, 제거 후에는 첫 배뇨 시간과 배뇨량, 잔뇨량을 확인한다. 여섯째, 증상 없는 세균뇨에 대해 관행적으로 항생제를 투여하거나 방광세척을 하지 않으며, 도뇨관 고정으로 당김을 방지하고 대상자와 보호자에게 관리 방법과 보고 기준을 교육한다.",
