          "answer": "① 잔뇨량(PVR)을 방광 초음파로 정기적으로 측정하고, 치골상부 팽윤과 촉진되는 방광, 하복부 불편감, 소변 줄기의 세기와 배뇨 후 잔뇨감을 함께 사정하여 경과를 기록한다. ② 이중배뇨법을 교육한다 — 배뇨 후 그대로 앉아 1~2분 기다렸다가 다시 한 번 배뇨하여 잔뇨를 줄이고, 서두르지 않고 충분한 시간과 프라이버시를 준다. 배뇨 자세는 발이 바닥에 닿게 앉아 편안히 힘을 빼도록 한다. ③ 배뇨를 유도하는 방법을 알려 준다 — 따뜻한 물에 손 담그기, 물 흐르는 소리 들려주기, 좌욕, 하복부에 따뜻한 물주머니 대기 등을 시도하고, 규칙적인 시간(기상 직후·식후·취침 전)에 배뇨를 시도하게 한다. 치골상부를 부드럽게 눌러 주는 방법(크레데법)은 지시가 있을 때만 시행한다. ④ 요저류를 악화시키는 약물을 지속적으로 관리한다 — 항콜린제, 1세대 항히스타민제, 삼환계 항우울제, 마약성 진통제, 일부 감기약을 임의로 복용하지 않게 하고, 새 약을 처방받거나 약국에서 살 때는 요폐 병력을 반드시 알리도록 교육한다. ⑤ 변비를 교정한다 — 직장에 찬 변이 방광과 요도를 눌러 배뇨를 방해하므로 수분·섬유질 섭취와 규칙적 배변 습관, 필요 시 처방된 완하제를 적용한다. 파킨슨병 자체가 변비를 잘 일으킨다는 점을 설명한다. ⑥ 수분을 하루 1,500~2,000mL 낮 동안 골고루 마시고 취침 2~3시간 전부터 줄이도록 하며, 카페인·알코올 등 방광 자극 물질을 제한한다. ⑦ 잔뇨가 계속 많으면 처방에 따라 간헐적 도뇨를 시행하며, 유치도뇨관은 요로감염 위험이 커서 최후의 수단으로만 쓰고 삽입했다면 필요성을 매일 재평가해 조기에 제거한다. ⑧ 보고해야 할 응급 징후를 교육한다 — 소변이 전혀 나오지 않고 아랫배가 팽팽하며 심하게 아픈 급성 요폐, 발열·탁한 소변·악취·혈뇨, 갑자기 멍해지거나 처지는 변화(노인 요로감염의 신호)는 즉시 알리도록 한다. 아울러 밤에 화장실에 갈 때 넘어지지 않도록 야간 조명, 안전손잡이, 미끄럼방지 매트를 갖추고 필요하면 침상 옆 이동식 변기를 두도록 한다.",
