          "answer": "① 의식과 인지의 변화 — 잠자는 시간이 점점 길어지고 불러도 잘 깨지 않으며 기면에서 혼수로 진행하고, 이미 돌아가신 분과 대화하는 임종 섬망이 나타날 수 있다. 청각은 마지막까지 남으므로 곁에서 부정적인 말을 하지 않도록 가족에게 알린다. ② 호흡의 변화 — 빨라졌다 느려졌다 하며 무호흡이 반복되는 체인-스토크스 호흡(Cheyne-Stokes respiration), 아래턱만 들썩이는 하악호흡, 불규칙하고 얕은 호흡이 나타난다. ③ 기도 분비물(임종 그르렁거림, death rattle) — 삼킴 반사가 약해져 인후두에 고인 분비물이 호흡 때마다 가르랑 소리를 내지만 본인은 괴롭지 않다. ④ 순환의 변화 — 혈압이 떨어지고 맥박은 빠르고 약해지며 말초 맥박이 만져지지 않는다. ⑤ 말초 순환 저하의 피부 소견 — 손발부터 차가워지고 무릎·발·손에 청자색 반점(mottling)이 생기며 입술과 손톱에 청색증이 나타난다. ⑥ 소변량 감소와 실금 — 신장 관류가 줄어 소변이 크게 줄고 색이 진해지며 괄약근 이완으로 대소변 실금이 생긴다. ⑦ 경구 섭취 중단과 삼킴 불능 — 먹고 마시려는 욕구가 사라지는 것은 임종 과정의 자연스러운 일부이며 배고픔·갈증으로 괴로운 상태가 아니다. ⑧ 안절부절못함과 반복적인 동작, 근간대경련 등 임종기 초조가 나타날 수 있다. 병원 이송이 적절하지 않은 이유는, 이 대상자가 적극적인 의학적 치료를 받지 않기로 스스로 결정하였고 완화의료의 목표가 완치가 아니라 안위와 존엄이기 때문이다. 임종 임박기의 이송은 익숙한 환경과 곁에 있는 가족으로부터 분리시키고, 응급실에서 침습적 처치를 반복하게 하여 남은 시간의 고통만 늘린다. 따라서 자기결정권 존중, 돌보는 사람들(간병인·의사)의 협조, 가능한 범위 내의 증상조절, 편안한 죽음에 대한 지지라는 네 가지 원칙에 따라 있던 자리에서 임종을 돕는 것이 옳다.",
