          "q": "암성통증으로 마약성 진통제를 투여받는 이 대상자가 투여 후 반혼수 상태에 빠지려 할 때 취해야 할 통증관리 방향을 밝히고, 임종기 마약성 진통제 사용 원칙 6가지를 서술하시오.",
          "answer": "반혼수 상태에 빠지더라도 대상자는 통증을 계속 느낄 수 있으므로 진통제를 중단해서는 안 되며, 소량의 진통제를 계속 투여하여 편안함을 유지하는 것이 바람직하다. 임종기 통증관리의 목표는 각성 수준의 회복이 아니라 안위 유지이므로, 의식이 떨어졌다는 이유로 투약을 끊으면 표현하지 못하는 통증을 방치하게 된다. 대신 진정 정도와 호흡수를 관찰하며 용량을 조절하고, 의사소통이 어려우므로 PAINAD 등 행동관찰 도구(호흡, 부정적 발성, 얼굴 표정, 몸짓, 위로 가능성)로 통증을 사정한다. 원칙은 다음과 같다. ① 세계보건기구(WHO) 3단계 진통사다리에 따라 통증 강도에 맞추어 약을 선택하되, 심한 통증에는 단계를 건너뛰어 바로 강한 마약성 진통제를 쓸 수 있다. ② 통증이 생기기를 기다리지 말고 정해진 시간에 규칙적으로 투여한다. ③ 갑자기 심해지는 돌발통에는 속효성 구제약을 하루 총 용량의 약 10%로 추가 투여하고, 구제약을 하루 3~4회 이상 사용하면 기본 용량 증량을 검토한다. ④ 마약성 진통제에는 천장효과가 없으므로 통증에 따라 증량할 수 있으나, 신기능이 저하된 노인에서는 대사산물이 축적되어 진정·근간대경련이 생기므로 감량한다. ⑤ 부작용을 예방적으로 관리한다 — 변비는 내성이 생기지 않으므로 처음부터 완하제를 함께 주고, 오심·졸림은 대개 3~5일 내 좋아짐을 설명하며, 소변저류·가려움을 관찰한다. ⑥ 경구 투여가 어려워지면 피하 지속주입·경피 패치·설하·직장 투여로 경로를 바꾸고, 진통제·항불안제·항구토제·항분비제만 남기고 나머지 약은 정리한다. ⑦ meperidine(페티딘)은 대사산물 축적으로 경련·섬망을 유발하여 노인에게 금기이며, 통증 조절을 위한 마약성 진통제 사용은 중독이나 수명 단축이 아님을 대상자와 가족에게 반복 설명한다.",
