          "q": "Kubler-Ross가 제시한 죽음에 대한 심리적 반응 5단계를 순서대로 쓰고 각 단계의 특징을 서술한 뒤, 이 대상자의 발언이 각각 어느 단계에 해당하는지 근거와 함께 판단하시오.",
          "answer": "① 부정(denial) — 진단이나 예후를 사실로 받아들이지 못하고 \"뭔가 잘못되었을 것이다\", \"검사가 틀렸다\"며 현실을 차단한다. 충격을 완충하는 방어기제로, 시간을 두고 스스로 받아들이도록 기다려 준다. ② 분노(anger) — \"왜 하필이면 내가\"라는 원망과 함께 적대감을 주위 사람이나 환경에 표출하고, 고함을 지르거나 파괴적인 행동을 보이며 의료진·가족에게 짜증을 낸다. 이 대상자가 며칠 전 보인 반응이 여기에 해당한다. ③ 협상(bargaining) — 죽음을 늦추거나 시간을 더 얻기 위해 신이나 운명과 흥정하려는 태도를 보인다. \"딸이 시집가기 전까지만 살게 해달라\", \"지난날의 실패를 보상하는 데 시간이 더 필요하다\"는 표현은 시간을 더 얻으려는 협상의 전형적인 모습이므로 현재 대상자는 협상단계에 있다. ④ 우울(depression) — 상실이 현실로 다가오면서 슬픔·무력감·위축이 나타나고 말수가 줄며 눈물을 자주 보인다. 이때의 슬픔은 병적인 것이 아니라 이별을 준비하는 예기 슬픔이므로 성급한 위로보다 함께 있어 주는 것이 필요하다. ⑤ 수용(acceptance) — 죽음을 담담히 받아들이고 주변을 정리하며 조용해진다. 감정 표현이 줄어 무관심으로 오해되기 쉬우나 실제로는 평온한 상태이다. 다만 이 단계들은 반드시 순서대로 진행하지 않으며 오가거나 겹칠 수 있으므로, 간호사는 단계를 판정하는 데 그치지 말고 지금 대상자가 표현하는 감정에 맞추어 반응해야 한다. 이 대상자 역시 분노에서 협상으로 이동한 것으로 보이나 다시 분노나 우울로 되돌아갈 수 있다.",
