          "answer": "① 감정 표현을 격려하고 지지적 관계를 맺는다 — 환자가 자신의 심리적 반응과 감정을 자유롭게 표현하도록 돕고, 곁에 머무르며 경청하여 의미 있고 지지적인 관계를 형성한다. 협상 내용을 비현실적이라고 지적하거나 소원을 단념시키려 하지 않는다. ② 소원을 수용하고 가능한 범위에서 실현되도록 돕는다 — 만나고 싶은 사람, 정리하고 싶은 일, 이루고 싶은 것을 확인하여 가족·팀과 함께 실행 계획을 세운다. 딸의 결혼처럼 실현이 어려운 일은 영상편지나 미리 여는 작은 예식 등 대안을 함께 찾는다. ③ 성급한 위로나 거짓 확신을 피한다 — \"괜찮아질 거예요\" 같은 말 대신 침묵과 손잡기 같은 비언어적 지지를 활용하고, 알고 싶어 하는 만큼의 정보를 정직하게 제공한다. ④ 미해결 과제와 화해의 기회를 만든다 — 회상과 생애 이야기 나누기를 통해 삶을 정리하도록 돕고, 감사·용서·사랑·작별의 말을 미루지 않고 전할 기회를 마련한다. \"지난날의 실패\"에 대한 죄책감을 표현하도록 하여 자책이 완화되도록 돕는다. ⑤ 영적 요구를 사정하고 연계한다 — 원하는 종교의식과 성직자 방문을 주선하고 기도·예배 등 의식에 참여할 수 있도록 배려한다. ⑥ 존엄과 프라이버시를 지킨다 — 처치 전 반드시 설명하고 동의를 구하며 이름을 불러 드리고, 의식이 없어 보여도 곁에서 부정적인 말을 하지 않는다(청각은 마지막까지 남는다). ⑦ 가족을 함께 지지한다 — 가족의 예기 슬픔을 정상 반응으로 인정하고 돌봄에 직접 참여할 기회를 주어 무력감을 줄이며, 환자의 협상 발언에 어떻게 반응하면 좋을지 구체적으로 안내한다.",
