          "answer": "가장 먼저 해야 할 일은 사생활을 보호하기 위한 커튼을 쳐 주는 것이다. 가족들의 가장 즉각적인 요청은 고인의 시신을 확인하는 일이며, 이때 가장 중요한 것이 사생활 보호이기 때문이다. 사망을 준비할 시간 없이 가족이 없는 상태에서 갑작스럽게 임종을 맞았으므로 가족은 충격과 죄책감이 큰 상태이고, 다른 사람들의 시선에 노출된 채 고인을 대면하면 슬픔을 표현하지 못한 채 억제하게 된다. 시신을 씻고 침대를 정리하기 위해 가족을 30분 뒤에 돌아오게 하거나 임종간호를 먼저 시행하는 것은 가족의 즉각적 요구를 뒤로 미루는 것이므로 우선순위가 아니다. 이후 간호중재는 다음과 같다. ① 조용하고 독립된 공간을 마련하여 가족이 고인과 충분히 시간을 보내고 마지막 인사를 하도록 한다. ② 사망 상황을 이해할 수 있는 말로 정직하게 설명하고, 곁에 있지 못한 것에 대한 죄책감을 표현하도록 하며 그것이 가족의 잘못이 아님을 알려 준다. ③ 애도 반응을 억제하지 않도록 돕는다 — 울음, 침묵, 분노, 멍한 반응이 모두 정상임을 설명하고 성급한 위로 대신 곁에 머물며 경청한다. ④ 가족이 원하면 고인의 몸을 닦고 옷을 갈아입히는 사후처치에 함께 참여하도록 하여 무력감을 줄이고 작별의 기회를 준다. 종교·문화적 관습과 의식 요구를 확인하여 존중한다. ⑤ 이후 절차를 차분히 안내한다 — 사망 진단과 사망진단서 발급, 유품 정리와 인계, 장례 절차, 미리 정해 둔 의향(장기·시신 기증 등)의 확인 방법을 알려 주고 필요하면 사회복지사와 연계한다. ⑥ 고인의 존엄을 지키는 사후처치를 시행하되 가족이 볼 수 있음을 늘 염두에 두고 조심스럽게 다룬다.",
