          "answer": "침의 IgA(면역글로불린 A)는 점막 표면에서 국소면역을 담당하는 항체로, 세균이 점막에 부착하는 것을 막고 독소를 중화한다. 두경부 방사선 조사로 침샘이 손상되면 침 분비 자체가 줄어들고 그와 함께 침 속 IgA도 저하되므로 구강 내 세균 증식을 억제하지 못하게 된다. 여기에 침의 세척작용과 완충작용(산 중화), 재석회화에 필요한 칼슘·인의 공급까지 함께 감소하므로 치아 표면이 산에 오래 노출되어 충치가 급속히 진행한다. 즉 충치는 IgA 감소를 포함한 침 분비 저하의 복합적 결과이다. 구강간호는 다음과 같다. ① 매 식후와 취침 전 부드러운 칫솔과 불소 함유 치약으로 닦고 정기적으로 치과 검진을 받으며 불소 도포를 시행한다. ② 알코올이 든 구강청결제는 점막을 더 건조시키므로 피하고, 생리식염수나 중조수(베이킹소다 용액)로 자주 헹군다. ③ 물을 조금씩 자주 마시고 얼음조각을 물고 있게 하며, 처방된 인공타액을 사용하고 입술에는 보습제를 바른다. ④ 침 분비를 자극하기 위해 무설탕 껌이나 신맛 나는 무설탕 사탕을 이용한다(단, 구내염이 있으면 자극이 되므로 주의한다). ⑤ 자당이 많은 음식과 음료, 끈적이고 딱딱한 음식, 뜨겁고 매운 음식, 술·담배를 피하고 부드럽고 촉촉한 음식을 제공한다. ⑥ 구강점막염·구강 칸디다증·출혈을 매일 관찰한다 — 백태, 발적, 통증, 궤양이 있으면 보고하고, 항암·방사선 치료로 면역이 저하되어 있으므로 감염 징후에 특히 주의한다. ⑦ 의치는 잘 맞는지 확인하고 밤에는 빼서 세척·보관하며, 통증으로 식사가 어려우면 국소 마취 함수액과 진통제를 식전에 사용하도록 한다.",
